    fn assert_direct_put_metadata_on_acting_nodes(
        map: &LocalClusterMap,
        node_ids: &[NodeId],
        object_pg: u32,
        commit_req: &crate::CommitDirectPutObjectReq,
        outcome: &crate::FinalizeDirectPutObjectOutcome,
    ) {
        let expected_segment = crate::ObjectSegmentRecord {
            bucket: commit_req.bucket.clone(),
            key: commit_req.key.clone(),
            version_id: outcome.version_id,
            segment_index: commit_req.segment_index,
            size: commit_req.size,
            segment_crc64: commit_req.segment_crc64,
            segment_okh: commit_req.segment_okh,
            segment_vid: commit_req.segment_vid,
            data_pg_id: commit_req.data_pg_id,
            ec_k: commit_req.ec.k,
            ec_m: commit_req.ec.m,
        };

        for node_id in node_ids {
            let node = map.node(*node_id).unwrap().storage_node();
            let pg = node.get_pg(object_pg).unwrap();
            let stored =
                crate::PgMetadataStore::get_object_meta(&*pg, &commit_req.bucket, &commit_req.key)
                    .unwrap();
            let live = stored.as_live().unwrap();
            assert_eq!(live.version_id, outcome.version_id);
            assert_eq!(live.generation_id, commit_req.generation_id);
            assert_eq!(live.size, commit_req.size);
            assert_eq!(
                live.etag,
                crate::ObjectEtag::single_part(commit_req.etag_crc64)
            );
            assert_eq!(live.last_modified, outcome.live_last_modified);
            assert_eq!(live.metadata_blob, Some(commit_req.metadata_blob.clone()));
            assert_eq!(
                live.system_metadata_blob,
                Some(commit_req.system_metadata_blob.clone())
            );
            assert_eq!(live.object_lock, commit_req.object_lock);
            assert_eq!(live.encryption, commit_req.encryption);
            assert_eq!(
                crate::PgMetadataStore::get_object_segments(
                    &*pg,
                    &commit_req.bucket,
                    &commit_req.key,
                    outcome.version_id,
                )
                .unwrap(),
                vec![expected_segment.clone()]
            );
            assert!(matches!(
                crate::PgMetadataStore::get_object_generation_reservation(
                    &*pg,
                    &commit_req.bucket,
                    &commit_req.key,
                    &commit_req.generation_reservation_id,
                ),
                Err(crate::MetadataError::ObjectGenerationReservationNotFound { .. })
            ));
        }
    }

    fn assert_object_version_counter_on_acting_nodes(
        map: &LocalClusterMap,
        node_ids: &[NodeId],
        object_pg: u32,
        bucket: &crate::BucketName,
        key: &crate::ObjectKey,
        expected_next_version_id: u64,
    ) {
        for node_id in node_ids {
            let node = map.node(*node_id).unwrap().storage_node();
            let pg = node.get_pg(object_pg).unwrap();
            let next_version_id: i64 = pg
                .connection()
                .query_row(
                    "SELECT COALESCE(MAX(next_version_id), 0) \
                     FROM object_version_counters WHERE bucket = ?1 AND key = ?2",
                    rusqlite::params![bucket.as_str(), key.as_str()],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(
                next_version_id as u64, expected_next_version_id,
                "unexpected object version counter on node {node_id:?}"
            );
        }
    }

    fn assert_bucket_execution_counter_on_acting_nodes(
        map: &LocalClusterMap,
        node_ids: &[NodeId],
        bucket_pg: u32,
        expected_current_generation: u64,
    ) {
        for node_id in node_ids {
            let node = map.node(*node_id).unwrap().storage_node();
            let pg = node.get_pg(bucket_pg).unwrap();
            let next_generation: i64 = pg
                .connection()
                .query_row(
                    "SELECT next_bucket_execution_generation \
                     FROM pg_counters WHERE singleton = 0",
                    [],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(
                next_generation as u64, expected_current_generation,
                "unexpected bucket execution counter on node {node_id:?}"
            );
        }
    }

    fn seed_streamed_multipart_completion(
        cluster: &crate::StorageCluster,
        bucket: &crate::BucketName,
        key: &crate::ObjectKey,
        upload_label: &str,
    ) -> (
        crate::CompleteMultipartCommitRequest,
        crate::MultipartPartSegmentRecord,
    ) {
        seed_streamed_multipart_completion_with_existing(cluster, bucket, key, upload_label, false)
    }

    fn seed_streamed_multipart_completion_with_existing(
        cluster: &crate::StorageCluster,
        bucket: &crate::BucketName,
        key: &crate::ObjectKey,
        upload_label: &str,
        expect_existing_object: bool,
    ) -> (
        crate::CompleteMultipartCommitRequest,
        crate::MultipartPartSegmentRecord,
    ) {
        let upload_id = upload_id_from_label(upload_label);
        cluster
            .create_multipart_upload(
                bucket,
                key,
                crate::BucketSnapshotRequest::default(),
                |_snapshot, existing_object| {
                    assert_eq!(existing_object.is_some(), expect_existing_object);
                    Ok::<_, ()>((
                        (),
                        crate::CreateMultipartUploadReq {
                            upload_id: upload_id.clone(),
                            bucket: bucket.clone(),
                            key: key.clone(),
                            tags: None,
                            metadata_blob: crate::SerializedMetadataBlob::default(),
                            system_metadata_blob: crate::SerializedSystemMetadataBlob::default(),
                            initiator: Some(crate::OwnerIdentity::from_principal("initiator")),
                            owner: crate::OwnerIdentity::from_principal("owner"),
                            acl_grants: crate::AclGrants::default(),
                            public_read: false,
                            object_lock: crate::ObjectLockState::default(),
                            checksum: None,
                            encryption: crate::ObjectEncryption::None,
                        },
                    ))
                },
            )
            .unwrap()
            .unwrap();
        let upload = cluster
            .load_in_progress_multipart_upload(bucket, key, &upload_id)
            .unwrap();
        let (_shard_keys, part, mut expected_segment) = upload_streamed_test_multipart_part(
            cluster,
            bucket,
            key,
            &upload_id,
            1,
            [0xCD; 16],
            b"streamed completion",
        );

        expected_segment.version_id = crate::VersionId::Null.to_u64();
        (
            crate::CompleteMultipartCommitRequest {
                bucket: bucket.clone(),
                key: key.clone(),
                upload_id,
                versioning: crate::BucketVersioningState::Disabled,
                owner: upload.owner,
                acl_grants: upload.acl_grants,
                public_read: upload.public_read,
                generation_id: upload.object_generation_id,
                size: part.size,
                etag_crc64: [0x44; 8],
                tags: upload.tags,
                metadata_blob: Some(upload.metadata_blob),
                system_metadata_blob: Some(upload.system_metadata_blob),
                object_lock: upload.object_lock,
                encryption: upload.encryption,
                part_records: vec![part],
            },
            expected_segment,
        )
    }

    fn pending_multipart_completion_command_for_test(
        map: &LocalClusterMap,
        cluster: &crate::StorageCluster,
        pg_id: PgId,
        req: &crate::CompleteMultipartCommitRequest,
        last_modified_millis: u64,
    ) -> (MetadataCommandEnvelope, u64) {
        let primary = map
            .metadata_pg_primary_node(ClusterEpoch::INITIAL, pg_id)
            .unwrap();
        let pg = primary.storage_node().get_pg(pg_id.get()).unwrap();
        let upload = crate::PgMetadataStore::get_multipart_upload(&*pg, &req.upload_id)
            .expect("seeded upload is still in progress");
        let parts_count =
            std::num::NonZeroU32::new(u32::try_from(req.part_records.len()).unwrap()).unwrap();
        let topology = primary.storage_node().pg_topology();
        let object_parts = req
            .part_records
            .iter()
            .map(|part| {
                let data_pg_id = topology
                    .object_generation_multipart_part_data_pg(
                        &req.bucket,
                        &req.key,
                        req.generation_id,
                        part.part_number,
                    )
                    .get();
                crate::ObjectPartRecord {
                    bucket: req.bucket.clone(),
                    key: req.key.clone(),
                    version_id: crate::VersionId::Null,
                    part_number: part.part_number,
                    size: part.size,
                    etag: part.etag.clone(),
                    etag_kind: part.etag_kind,
                    part_okh: part.part_okh,
                    part_vid: part.part_vid,
                    ec_k: part.ec_k,
                    ec_m: part.ec_m,
                    data_pg_id,
                    checksum: part.checksum.clone(),
                }
            })
            .collect::<Vec<_>>();
        let mut selected_streaming_segments =
            crate::PgMetadataStore::get_all_multipart_part_segments_for_upload(
                &*pg,
                &req.upload_id,
            )
            .unwrap();
        for segment in &mut selected_streaming_segments {
            segment.version_id = crate::VersionId::Null.to_u64();
        }
        let write_sequence = pg
            .next_object_write_sequence(req.bucket.as_str(), req.key.as_str())
            .unwrap();
        drop(pg);
        let completion_order = cluster
            .test_reserve_completed_multipart_upload_order(&req.bucket)
            .unwrap();
        let bucket_write_reservation = acquire_test_bucket_write_proof(
            cluster,
            &req.bucket,
            "test-complete-multipart",
            Some(req.key.as_str()),
        );
        (
            MetadataCommandEnvelope::new(
                MetadataCommandId::new(
                    ClusterEpoch::INITIAL,
                    pg_id,
                    map.test_next_metadata_command_log_index(pg_id),
                ),
                MetadataCommandPayload::CommitMultipartObject(Box::new(
                    CommitMultipartObjectCommand {
                        upload_id: req.upload_id.clone(),
                        bucket_write_reservation,
                        object: crate::PutLiveObjectReq {
                            bucket: req.bucket.clone(),
                            key: req.key.clone(),
                            version_id: crate::VersionId::Null,
                            owner: req.owner.clone(),
                            acl_grants: req.acl_grants.clone(),
                            public_read: req.public_read,
                            generation_id: req.generation_id,
                            size: req.size,
                            etag: crate::ObjectEtag::MultipartComposite {
                                crc64: req.etag_crc64,
                                parts: parts_count,
                            },
                            ec: EcShape { k: 0, m: 0 },
                            layout: crate::ObjectLayout::MultipartManifest { parts_count },
                            tags: req.tags.clone(),
                            metadata_blob: req.metadata_blob.clone(),
                            system_metadata_blob: req.system_metadata_blob.clone(),
                            object_lock: req.object_lock,
                            encryption: req.encryption.clone(),
                        },
                        parts: object_parts,
                        selected_streaming_segments,
                        omitted_parts: Vec::new(),
                        omitted_streaming_segments: Vec::new(),
                        stream_uploads: Vec::new(),
                        stream_upload_segments: Vec::new(),
                        write_sequence,
                        completion_order,
                        completed_at_millis: last_modified_millis,
                        initiator: upload.initiator.clone(),
                        last_modified_millis,
                        stale_payload: None,
                    },
                )),
            ),
            write_sequence,
        )
    }

    fn assert_streamed_multipart_completion_on_acting_nodes(
        map: &LocalClusterMap,
        node_ids: &[NodeId],
        object_pg: u32,
        req: &crate::CompleteMultipartCommitRequest,
        expected_segment: &crate::MultipartPartSegmentRecord,
        outcome: &crate::CompleteMultipartCommitOutcome,
    ) {
        assert_streamed_multipart_completion_on_acting_nodes_with_write_sequence(
            map,
            node_ids,
            object_pg,
            req,
            expected_segment,
            outcome,
            1,
        );
    }

    fn assert_streamed_multipart_completion_on_acting_nodes_with_write_sequence(
        map: &LocalClusterMap,
        node_ids: &[NodeId],
        object_pg: u32,
        req: &crate::CompleteMultipartCommitRequest,
        expected_segment: &crate::MultipartPartSegmentRecord,
        outcome: &crate::CompleteMultipartCommitOutcome,
        expected_write_sequence: u64,
    ) {
        let mut expected_completion_order = None;
        for node_id in node_ids {
            let node = map.node(*node_id).unwrap().storage_node();
            let pg = node.get_pg(object_pg).unwrap();
            let stored = crate::PgMetadataStore::get_object_meta(&*pg, &req.bucket, &req.key)
                .unwrap()
                .as_live()
                .unwrap()
                .clone();
            assert_eq!(stored.version_id, outcome.version_id);
            assert_eq!(stored.generation_id, req.generation_id);
            assert_eq!(stored.size, req.size);
            assert_eq!(stored.last_modified, outcome.live_last_modified);
            assert_eq!(stored.layout.parts_count(), Some(1));
            assert_eq!(
                pg.object_write_sequence(req.bucket.as_str(), req.key.as_str(), outcome.version_id)
                    .unwrap(),
                Some(expected_write_sequence)
            );

            let parts = crate::PgMetadataStore::get_object_parts(
                &*pg,
                &req.bucket,
                &req.key,
                outcome.version_id,
            )
            .unwrap();
            assert_eq!(parts.len(), 1);
            assert_eq!(parts[0].part_okh, [0u8; 16]);
            assert_eq!(parts[0].part_vid, req.part_records[0].part_vid);

            let segments = crate::PgMetadataStore::get_multipart_part_segments(
                &*pg,
                &req.bucket,
                &req.key,
                outcome.version_id,
                1,
            )
            .unwrap();
            assert_eq!(segments, vec![expected_segment.clone()]);
            assert!(matches!(
                crate::PgMetadataStore::get_multipart_upload(&*pg, &req.upload_id),
                Err(crate::MetadataError::NoSuchUpload { .. })
            ));
            let completed_uploads = pg
                .list_completed_multipart_uploads_for_bucket(req.bucket.as_str())
                .unwrap();
            assert_eq!(completed_uploads.len(), 1);
            assert_eq!(completed_uploads[0].0, req.upload_id);
            if let Some(expected) = expected_completion_order {
                assert_eq!(completed_uploads[0].1, expected);
            } else {
                expected_completion_order = Some(completed_uploads[0].1);
            }
            let bucket_pg = node
                .get_pg(node.pg_topology().bucket_pg_for(&req.bucket))
                .unwrap();
            assert_eq!(
                bucket_pg
                    .completed_multipart_upload_sequence_for_bucket(&req.bucket)
                    .unwrap(),
                completed_uploads[0].1
            );
        }
    }

    fn completed_multipart_order_on_node(
        map: &LocalClusterMap,
        node_id: NodeId,
        object_pg: u32,
        bucket: &crate::BucketName,
        upload_id: &crate::UploadId,
    ) -> u64 {
        let node = map.node(node_id).unwrap().storage_node();
        let pg = node.get_pg(object_pg).unwrap();
        pg.list_completed_multipart_uploads_for_bucket(bucket.as_str())
            .unwrap()
            .into_iter()
            .find_map(|(stored_upload_id, completion_order)| {
                (stored_upload_id == *upload_id).then_some(completion_order)
            })
            .unwrap_or_else(|| panic!("completed upload {upload_id:?} not found on PG {object_pg}"))
    }

    fn seed_bucket_record(
        map: &LocalClusterMap,
        node_id: NodeId,
        pg_id: u32,
        bucket: &crate::BucketName,
        owner: &crate::CanonicalUserId,
    ) {
        let node = map.node(node_id).unwrap().storage_node();
        let pg = node.get_pg(pg_id).unwrap();
        crate::PgMetadataStore::create_bucket(
            &*pg,
            bucket,
            "owner",
            owner,
            &crate::AclGrants::default(),
            false,
            false,
        )
        .unwrap();
    }

    fn upload_id_from_label(label: &str) -> crate::UploadId {
        let mut upload_id = String::from(label);
        upload_id.extend(std::iter::repeat_n(
            '.',
            crate::UPLOAD_ID_LEN - upload_id.len(),
        ));
        crate::UploadId::try_from(upload_id).unwrap()
    }

    fn seed_multipart_upload_record(
        map: &LocalClusterMap,
        node_id: NodeId,
        pg_id: u32,
        bucket: &crate::BucketName,
        key: &crate::ObjectKey,
        upload_id: &crate::UploadId,
        state: crate::UploadState,
    ) {
        let node = map.node(node_id).unwrap().storage_node();
        let pg = node.get_pg(pg_id).unwrap();
        crate::PgMetadataStore::create_multipart_upload(
            &*pg,
            &crate::CreateMultipartUploadReq {
                upload_id: upload_id.clone(),
                bucket: bucket.clone(),
                key: key.clone(),
                tags: None,
                metadata_blob: crate::SerializedMetadataBlob::default(),
                system_metadata_blob: crate::SerializedSystemMetadataBlob::default(),
                initiator: None,
                owner: crate::OwnerIdentity::from_principal("owner"),
                acl_grants: crate::AclGrants::default(),
                public_read: false,
                object_lock: crate::ObjectLockState::default(),
                checksum: None,
                encryption: crate::ObjectEncryption::None,
            },
        )
        .unwrap();
        if state != crate::UploadState::InProgress {
            crate::PgMetadataStore::set_upload_state(&*pg, upload_id, state).unwrap();
            pg.refresh_metadata_command_state_digest().unwrap();
        }
    }

    fn upload_streamed_test_multipart_part(
        cluster: &crate::StorageCluster,
        bucket: &crate::BucketName,
        key: &crate::ObjectKey,
        upload_id: &crate::UploadId,
        part_number: u32,
        segment_okh: [u8; 16],
        payload: &[u8],
    ) -> (
        Vec<ShardKey>,
        crate::MultipartPartRecord,
        crate::MultipartPartSegmentRecord,
    ) {
        let session_seed = segment_okh[0];
        let session_id =
            crate::SessionId::try_from(format!("{session_seed:02x}").repeat(16)).unwrap();
        let upload = cluster
            .load_in_progress_multipart_upload(bucket, key, upload_id)
            .unwrap();
        cluster
            .create_upload_part_stream_session(
                &crate::AuthorizedMultipartUploadRecord::assume_authorized(upload),
                part_number,
                &session_id,
            )
            .unwrap();

        let (_target, segment) = cluster
            .prepare_stream_segment_append(
                bucket,
                key,
                &crate::PrepareStreamUploadSegmentAppendReq {
                    session_id: session_id.clone(),
                    segment_index: 0,
                    size: payload.len() as u64,
                    segment_crc64: Some(checksum::crc64::checksum(payload)),
                    segment_okh,
                },
            )
            .unwrap();
        let written_shards = cluster
            .write_stream_segment_payload_shards(&segment, payload)
            .unwrap();
        let shard_batch = written_shards
            .iter()
            .map(|written| (&written.key, written.ack))
            .collect::<Vec<_>>();
        cluster
            .commit_stream_segment_append(
                bucket,
                key,
                &session_id,
                segment.segment_index,
                &segment,
                &shard_batch,
            )
            .unwrap();

        let part = cluster
            .finalize_upload_part_stream(
                bucket,
                key,
                upload_id,
                &session_id,
                part_number,
                |snapshot| {
                    let generation = snapshot
                        .existing_part_generation
                        .map_or(0, |generation| generation + 1);
                    let part = crate::MultipartPartRecord {
                        upload_id: upload_id.clone(),
                        part_number,
                        generation,
                        size: payload.len() as u64,
                        etag: vec![session_seed; 8],
                        etag_kind: crate::EtagKind::Crc64,
                        part_okh: [0u8; 16],
                        part_vid: crate::GenerationId::new(u64::from(generation) + 1).unwrap(),
                        ec_k: segment.ec_k,
                        ec_m: segment.ec_m,
                        last_modified: 123,
                        checksum: None,
                    };
                    let segments = snapshot
                        .staging_segments
                        .iter()
                        .map(|staged| crate::MultipartPartSegmentRecord {
                            bucket: bucket.clone(),
                            key: key.clone(),
                            upload_id: upload_id.clone(),
                            version_id: crate::MULTIPART_PART_SEGMENT_STAGING_VERSION_ID.to_u64(),
                            part_number,
                            segment_index: staged.segment_index,
                            size: staged.size,
                            segment_crc64: staged.segment_crc64,
                            segment_okh: staged.segment_okh,
                            segment_vid: staged.segment_vid,
                            data_pg_id: staged.data_pg_id,
                            ec_k: staged.ec_k,
                            ec_m: staged.ec_m,
                        })
                        .collect::<Vec<_>>();
                    Ok::<_, ()>(crate::PreparedStreamPartCommit {
                        value: part.clone(),
                        part,
                        segments,
                    })
                },
            )
            .unwrap()
            .unwrap()
            .value;

        let uploaded_segment = crate::MultipartPartSegmentRecord {
            bucket: bucket.clone(),
            key: key.clone(),
            upload_id: upload_id.clone(),
            version_id: crate::MULTIPART_PART_SEGMENT_STAGING_VERSION_ID.to_u64(),
            part_number,
            segment_index: segment.segment_index,
            size: segment.size,
            segment_crc64: segment.segment_crc64,
            segment_okh: segment.segment_okh,
            segment_vid: segment.segment_vid,
            data_pg_id: segment.data_pg_id,
            ec_k: segment.ec_k,
            ec_m: segment.ec_m,
        };
        (
            written_shards
                .into_iter()
                .map(|written| written.key)
                .collect(),
            part,
            uploaded_segment,
        )
    }

    fn seed_completed_multipart_upload_record(
        map: &LocalClusterMap,
        node_id: NodeId,
        pg_id: u32,
        bucket: &crate::BucketName,
        key: &crate::ObjectKey,
        upload_id: &crate::UploadId,
        completion_order: u64,
    ) {
        seed_multipart_upload_record(
            map,
            node_id,
            pg_id,
            bucket,
            key,
            upload_id,
            crate::UploadState::InProgress,
        );
        let node = map.node(node_id).unwrap().storage_node();
        let pg = node.get_pg(pg_id).unwrap();
        let upload = crate::PgMetadataStore::get_multipart_upload(&*pg, upload_id).unwrap();
        let version_id = crate::VersionId::Null;
        let part = crate::ObjectPartRecord {
            bucket: bucket.clone(),
            key: key.clone(),
            version_id,
            part_number: 1,
            size: 1,
            etag: vec![completion_order as u8; 8],
            etag_kind: crate::EtagKind::Crc64,
            part_okh: [completion_order as u8; 16],
            part_vid: upload.object_generation_id,
            ec_k: 2,
            ec_m: 1,
            data_pg_id: pg_id,
            checksum: None,
        };
        crate::PgMetadataStore::complete_multipart_commit(
            &*pg,
            upload_id,
            completion_order,
            &crate::CommitMultipartReq {
                bucket: bucket.clone(),
                key: key.clone(),
                version_id,
                owner: crate::OwnerIdentity::from_principal("owner"),
                acl_grants: crate::AclGrants::default(),
                public_read: false,
                generation_id: upload.object_generation_id,
                size: part.size,
                etag_crc64: [completion_order as u8; 8],
                ec: EcShape { k: 2, m: 1 },
                tags: None,
                metadata_blob: None,
                system_metadata_blob: None,
                object_lock: crate::ObjectLockState::default(),
                encryption: crate::ObjectEncryption::None,
            },
            &[part],
        )
        .unwrap();
        pg.connection()
            .execute(
                "UPDATE completed_multipart_uploads SET completed_at = ?1 WHERE upload_id = ?2",
                rusqlite::params![completion_order as i64, upload_id.as_str()],
            )
            .unwrap();
        pg.refresh_metadata_command_state_digest().unwrap();
    }

    fn set_route_primary(map: &mut LocalClusterMap, pg_id: u32, primary_node_id: NodeId) {
        let route = map.pg_routes.get_mut(&PgId::new(pg_id)).unwrap();
        route.acting_set = Arc::from([NodeId::new(0), NodeId::new(1), NodeId::new(2)]);
        route.primary_node_id = primary_node_id;
    }

    #[derive(Debug, Clone)]
    enum LocalClusterTraceOp {
        AdvanceEpoch,
        SetPgState(PgState),
        WriteCurrent(u8),
        WriteStale(u8),
        ReadCurrent,
        ReadStale,
        DeleteCurrent,
        DeleteStale,
        MetadataOperationStale(u8),
        ZeroSizeStalePayloadRead,
        QueueCurrent(u8),
        QueueStale(u8),
        LeaseReleaseAcrossEpoch(u8),
        RecoverAfterPhysicalShardLoss(u8),
        DrainPendingCreateBucketFromSecondHandle(u8),
        RestartAndValidate,
        ReissueDuplicateCreateBucketIndex(u8),
    }

    #[derive(Debug, Clone)]
    struct TraceWrittenShard {
        placement_key: Vec<u8>,
        location: ShardLocation,
        key: ShardKey,
        ack: WriteAck,
        data: Vec<u8>,
    }

    fn local_cluster_trace_strategy() -> impl Strategy<Value = Vec<LocalClusterTraceOp>> {
        prop::collection::vec(
            prop_oneof![
                2 => Just(LocalClusterTraceOp::AdvanceEpoch),
                3 => pg_state_strategy().prop_map(LocalClusterTraceOp::SetPgState),
                5 => any::<u8>().prop_map(LocalClusterTraceOp::WriteCurrent),
                3 => any::<u8>().prop_map(LocalClusterTraceOp::WriteStale),
                4 => Just(LocalClusterTraceOp::ReadCurrent),
                3 => Just(LocalClusterTraceOp::ReadStale),
                3 => Just(LocalClusterTraceOp::DeleteCurrent),
                2 => Just(LocalClusterTraceOp::DeleteStale),
                3 => any::<u8>().prop_map(LocalClusterTraceOp::MetadataOperationStale),
                3 => Just(LocalClusterTraceOp::ZeroSizeStalePayloadRead),
                2 => any::<u8>().prop_map(LocalClusterTraceOp::QueueCurrent),
                2 => any::<u8>().prop_map(LocalClusterTraceOp::QueueStale),
                2 => any::<u8>().prop_map(LocalClusterTraceOp::LeaseReleaseAcrossEpoch),
                1 => any::<u8>().prop_map(LocalClusterTraceOp::RecoverAfterPhysicalShardLoss),
                1 => any::<u8>().prop_map(LocalClusterTraceOp::DrainPendingCreateBucketFromSecondHandle),
                1 => Just(LocalClusterTraceOp::RestartAndValidate),
                1 => any::<u8>().prop_map(LocalClusterTraceOp::ReissueDuplicateCreateBucketIndex),
            ],
            1..=40,
        )
    }

    fn pg_state_strategy() -> impl Strategy<Value = PgState> {
        prop_oneof![
            Just(PgState::Active),
            Just(PgState::Peering),
            Just(PgState::Degraded),
            Just(PgState::Backfilling),
            Just(PgState::Inconsistent),
        ]
    }

    fn trace_node_ids() -> [NodeId; 6] {
        [
            NodeId::new(0),
            NodeId::new(1),
            NodeId::new(2),
            NodeId::new(3),
            NodeId::new(4),
            NodeId::new(5),
        ]
    }

    fn current_cluster(map: &Arc<LocalClusterMap>) -> Arc<crate::StorageCluster> {
        crate::StorageCluster::from_local_map(Arc::clone(map)).unwrap()
    }

    fn stale_cluster(
        map: &Arc<LocalClusterMap>,
        current_epoch: ClusterEpoch,
    ) -> Arc<crate::StorageCluster> {
        crate::StorageCluster::test_from_local_map_with_epoch(
            Arc::clone(map),
            stale_epoch_for(current_epoch),
        )
        .unwrap()
    }

    fn stale_epoch_for(current_epoch: ClusterEpoch) -> ClusterEpoch {
        if current_epoch == ClusterEpoch::INITIAL {
            ClusterEpoch::new(2).unwrap()
        } else {
            ClusterEpoch::INITIAL
        }
    }

    fn set_trace_epoch(map: &mut Arc<LocalClusterMap>, epoch: ClusterEpoch) {
        let map = Arc::get_mut(map).expect("trace must not retain StorageCluster handles");
        map.epoch = epoch;
        for route in map.pg_routes.values_mut() {
            route.cluster_epoch = epoch;
        }
    }

    fn set_trace_pg_state(map: &mut Arc<LocalClusterMap>, state: PgState) {
        let map = Arc::get_mut(map).expect("trace must not retain StorageCluster handles");
        map.pg_routes.get_mut(&PgId::new(0)).unwrap().state = state;
    }

    fn trace_bucket(seed: u8) -> crate::BucketName {
        crate::BucketName::try_from(format!("trace-bucket-{seed}")).unwrap()
    }

    fn trace_key(seed: u8) -> crate::ObjectKey {
        crate::ObjectKey::try_from(format!("trace-key-{seed}")).unwrap()
    }

    fn trace_session(seed: u8) -> crate::SessionId {
        crate::SessionId::try_from(format!("{:032x}", u128::from(seed) + 1)).unwrap()
    }

    fn trace_generation(seed: u8) -> crate::GenerationId {
        crate::GenerationId::new(u64::from(seed) + 1).unwrap()
    }

    fn trace_shard_key(step: usize, seed: u8) -> ShardKey {
        ShardKey::new(&[seed.wrapping_add(1); 16], 10_000 + step as u64, 0)
    }

    fn trace_bucket_for_pg(
        map: &LocalClusterMap,
        target_pg_id: u32,
        prefix: &str,
    ) -> crate::BucketName {
        let topology = map
            .node(NodeId::new(0))
            .unwrap()
            .storage_node()
            .pg_topology();
        bucket_for_pg(topology, target_pg_id, prefix)
    }

    fn trace_placement_key(step: usize, seed: u8) -> Vec<u8> {
        format!("trace-placement-{step}-{seed}").into_bytes()
    }

    fn current_trace_location(
        cluster: &crate::StorageCluster,
        written: &TraceWrittenShard,
        ec_shape: EcShape,
    ) -> ShardLocation {
        cluster
            .place_payload_shards(
                DataPgId::new(PgId::new(0)),
                ec_shape,
                &written.placement_key,
            )
            .unwrap()[usize::from(written.key.shard_index().get())]
    }

    fn written_trace_location_for_epoch(
        written: &TraceWrittenShard,
        current_epoch: ClusterEpoch,
    ) -> ShardLocation {
        ShardLocation::new(
            current_epoch,
            written.location.data_pg_id(),
            written.location.shard_index(),
            written.location.node_id(),
        )
    }

    fn arbitrary_current_location(current_epoch: ClusterEpoch) -> ShardLocation {
        ShardLocation::new(
            current_epoch,
            DataPgId::new(PgId::new(0)),
            ShardIndex::new(0),
            NodeId::new(0),
        )
    }

    fn shard_file_present_on_any_trace_node(map: &LocalClusterMap, key: &ShardKey) -> bool {
        trace_node_ids().into_iter().any(|node_id| {
            map.node(node_id)
                .unwrap()
                .storage_node()
                .read_shard_file(0, key)
                .is_ok()
        })
    }

    fn drain_trace_reclaim_work(cluster: &crate::StorageCluster) {
        while cluster.try_take_reclaim_work().is_some() {}
    }

    fn assert_stale_metadata_operation_error(
        err: crate::ObjectPgActionError,
        current_epoch: ClusterEpoch,
    ) -> TestCaseResult {
        let expected = matches!(
            err,
            crate::ObjectPgActionError::Store(StoreError::StaleMetadataOperation {
                pg_id: 0,
                operation_epoch,
                current_epoch: err_current_epoch,
            }) if operation_epoch == stale_epoch_for(current_epoch)
                && err_current_epoch == current_epoch
        );
        prop_assert!(expected, "unexpected metadata operation error: {err:?}");
        Ok(())
    }

    fn run_local_cluster_trace(ops: &[LocalClusterTraceOp]) -> TestCaseResult {
        let tmp = test_util::tempdir();
        let ec_shape = SharedStorageNode::DEFAULT_EC_SHAPE;
        let node_ids = trace_node_ids();
        let mut map =
            Arc::new(LocalClusterMap::open(tmp.path(), &node_ids, &[0], ec_shape).unwrap());
        let mut current_epoch = ClusterEpoch::INITIAL;
        let mut visited_epochs = BTreeSet::from([current_epoch]);
        let mut pg_state = PgState::Active;
        let mut written = None::<TraceWrittenShard>;

        for (step, op) in ops.iter().enumerate() {
            match op {
                LocalClusterTraceOp::AdvanceEpoch => {
                    current_epoch = ClusterEpoch::new(current_epoch.get() + 1).unwrap();
                    visited_epochs.insert(current_epoch);
                    set_trace_epoch(&mut map, current_epoch);
                }
                LocalClusterTraceOp::SetPgState(state) => {
                    pg_state = *state;
                    set_trace_pg_state(&mut map, pg_state);
                }
                LocalClusterTraceOp::WriteCurrent(seed) => {
                    let cluster = current_cluster(&map);
                    let placement_key = trace_placement_key(step, *seed);
                    let key = trace_shard_key(step, *seed);
                    let data = format!("trace-payload-{step}-{seed}").into_bytes();
                    match cluster.place_payload_shards(
                        DataPgId::new(PgId::new(0)),
                        ec_shape,
                        &placement_key,
                    ) {
                        Ok(locations) => {
                            prop_assert_eq!(pg_state, PgState::Active);
                            let location = locations[usize::from(key.shard_index().get())];
                            let ack = cluster.write_payload_shard(location, &key, &data).unwrap();
                            let read = cluster.read_payload_shard(location, &key, ack).unwrap();
                            prop_assert_eq!(read.as_slice(), data.as_slice());
                            written = Some(TraceWrittenShard {
                                placement_key,
                                location,
                                key,
                                ack,
                                data,
                            });
                        }
                        Err(ClusterBuildError::PgNotActive { state, .. }) => {
                            prop_assert_eq!(state, pg_state);
                            prop_assert!(!shard_file_present_on_any_trace_node(&map, &key));
                        }
                        Err(err) => return Err(TestCaseError::fail(format!("{err:?}"))),
                    }
                }
                LocalClusterTraceOp::WriteStale(seed) => {
                    let cluster = stale_cluster(&map, current_epoch);
                    let key = trace_shard_key(step, *seed);
                    let err = cluster
                        .write_payload_shard(
                            arbitrary_current_location(current_epoch),
                            &key,
                            b"stale write",
                        )
                        .unwrap_err();
                    let expected = matches!(
                        err,
                        ShardIoError::StaleOperationEpoch {
                            operation_epoch,
                            current_epoch: err_current_epoch,
                            ..
                        } if operation_epoch == stale_epoch_for(current_epoch)
                            && err_current_epoch == current_epoch
                    );
                    prop_assert!(expected, "unexpected stale write error: {err:?}");
                    prop_assert!(!shard_file_present_on_any_trace_node(&map, &key));
                }
                LocalClusterTraceOp::ReadCurrent => {
                    let Some(written) = written.as_ref() else {
                        continue;
                    };
                    let cluster = current_cluster(&map);
                    if pg_state == PgState::Active {
                        let location = current_trace_location(&cluster, written, ec_shape);
                        let read = cluster
                            .read_payload_shard(location, &written.key, written.ack)
                            .unwrap();
                        prop_assert_eq!(read.as_slice(), written.data.as_slice());
                    } else {
                        let location = written_trace_location_for_epoch(written, current_epoch);
                        let err = cluster
                            .read_payload_shard(location, &written.key, written.ack)
                            .unwrap_err();
                        let expected = matches!(
                            err,
                            ShardIoError::PgNotActive { state, .. } if state == pg_state
                        );
                        prop_assert!(expected, "unexpected inactive read error: {err:?}");
                        prop_assert!(shard_file_present_on_any_trace_node(&map, &written.key));
                    }
                }
                LocalClusterTraceOp::ReadStale => {
                    let key = written
                        .as_ref()
                        .map(|written| written.key.clone())
                        .unwrap_or_else(|| trace_shard_key(step, 0));
                    let ack = written
                        .as_ref()
                        .map(|written| written.ack)
                        .unwrap_or(WriteAck {
                            crc64: 0,
                            stored_size: 1,
                        });
                    let cluster = stale_cluster(&map, current_epoch);
                    let err = cluster
                        .read_payload_shard(arbitrary_current_location(current_epoch), &key, ack)
                        .unwrap_err();
                    let expected = matches!(
                        err,
                        ShardIoError::StaleOperationEpoch {
                            operation_epoch,
                            current_epoch: err_current_epoch,
                            ..
                        } if operation_epoch == stale_epoch_for(current_epoch)
                            && err_current_epoch == current_epoch
                    );
                    prop_assert!(expected, "unexpected stale read error: {err:?}");
                }
                LocalClusterTraceOp::DeleteCurrent => {
                    let Some(previous) = written.clone() else {
                        continue;
                    };
                    let cluster = current_cluster(&map);
                    if pg_state == PgState::Active {
                        let location = current_trace_location(&cluster, &previous, ec_shape);
                        cluster
                            .delete_payload_shard(location, &previous.key)
                            .unwrap();
                        prop_assert!(!shard_file_present_on_any_trace_node(&map, &previous.key));
                        written = None;
                    } else {
                        let location = written_trace_location_for_epoch(&previous, current_epoch);
                        let err = cluster
                            .delete_payload_shard(location, &previous.key)
                            .unwrap_err();
                        let expected = matches!(
                            err,
                            ShardIoError::PgNotActive { state, .. } if state == pg_state
                        );
                        prop_assert!(expected, "unexpected inactive delete error: {err:?}");
                        prop_assert!(shard_file_present_on_any_trace_node(&map, &previous.key));
                    }
                }
                LocalClusterTraceOp::DeleteStale => {
                    let Some(previous) = written.as_ref() else {
                        continue;
                    };
                    let cluster = stale_cluster(&map, current_epoch);
                    let err = cluster
                        .delete_payload_shard(
                            arbitrary_current_location(current_epoch),
                            &previous.key,
                        )
                        .unwrap_err();
                    let expected = matches!(
                        err,
                        ShardIoError::StaleOperationEpoch {
                            operation_epoch,
                            current_epoch: err_current_epoch,
                            ..
                        } if operation_epoch == stale_epoch_for(current_epoch)
                            && err_current_epoch == current_epoch
                    );
                    prop_assert!(expected, "unexpected stale delete error: {err:?}");
                    prop_assert!(shard_file_present_on_any_trace_node(&map, &previous.key));
                }
                LocalClusterTraceOp::MetadataOperationStale(seed) => {
                    let cluster = stale_cluster(&map, current_epoch);
                    let bucket = trace_bucket(*seed);
                    let key = trace_key(*seed);
                    let reservation_id = trace_session(*seed);
                    let err = cluster
                        .reserve_put_object_generation(&bucket, &key, &reservation_id)
                        .unwrap_err();
                    assert_stale_metadata_operation_error(err, current_epoch)?;
                    let cluster = current_cluster(&map);
                    let err = cluster
                        .test_object_generation_reservation_for(&bucket, &key, &reservation_id)
                        .unwrap_err();
                    let expected = matches!(
                        err,
                        crate::ObjectPgActionError::Metadata(
                            crate::MetadataError::ObjectGenerationReservationNotFound { .. }
                        )
                    );
                    prop_assert!(expected, "unexpected reservation lookup error: {err:?}");
                }
                LocalClusterTraceOp::ZeroSizeStalePayloadRead => {
                    let cluster = stale_cluster(&map, current_epoch);
                    let mut dst = vec![0xAA];
                    let err = cluster
                        .read_segment_payload_stored_bytes_into(
                            crate::SegmentStoredBytesRequest {
                                data_pg_id: 0,
                                segment_okh: [step as u8; 16],
                                segment_vid: crate::GenerationId::MIN,
                                stored_size: 0,
                                segment_crc64: Some(0),
                                ec: ec_shape,
                            },
                            &mut dst,
                        )
                        .unwrap_err();
                    let expected = matches!(
                        err,
                        StoreError::StalePayloadOperation {
                            pg_id: 0,
                            operation_epoch,
                            current_epoch: err_current_epoch,
                        } if operation_epoch == stale_epoch_for(current_epoch)
                            && err_current_epoch == current_epoch
                    );
                    prop_assert!(expected, "unexpected stale zero-size read error: {err:?}");
                    prop_assert_eq!(dst, vec![0xAA]);
                }
                LocalClusterTraceOp::QueueCurrent(seed) => {
                    let cluster = current_cluster(&map);
                    drain_trace_reclaim_work(&cluster);
                    let bucket = trace_bucket(*seed);
                    let key = trace_key(*seed);
                    let generation_id = trace_generation(*seed);
                    cluster.enqueue_object_payload_reclaim(&bucket, &key, generation_id);
                    let work = cluster.try_take_reclaim_work();
                    let expected = matches!(
                        work,
                        Some(crate::ReclaimWorkItem::ObjectPayload((
                            queued_bucket,
                            queued_key,
                            queued_generation_id
                        ))) if queued_bucket == bucket
                            && queued_key == key
                            && queued_generation_id == generation_id
                    );
                    prop_assert!(expected, "unexpected reclaim work item");
                    drain_trace_reclaim_work(&cluster);
                }
                LocalClusterTraceOp::QueueStale(seed) => {
                    let cluster = current_cluster(&map);
                    drain_trace_reclaim_work(&cluster);
                    drop(cluster);
                    let cluster = stale_cluster(&map, current_epoch);
                    cluster.enqueue_object_payload_reclaim(
                        &trace_bucket(*seed),
                        &trace_key(*seed),
                        trace_generation(*seed),
                    );
                    drop(cluster);
                    let cluster = current_cluster(&map);
                    prop_assert!(cluster.try_take_reclaim_work().is_none());
                }
                LocalClusterTraceOp::LeaseReleaseAcrossEpoch(seed) => {
                    let bucket = trace_bucket(*seed);
                    let key = trace_key(*seed);
                    let generation_id = trace_generation(*seed);
                    let cluster = current_cluster(&map);
                    if pg_state != PgState::Active {
                        let err = match cluster.acquire_object_payload_lease(
                            &bucket,
                            &key,
                            generation_id,
                        ) {
                            Ok(_) => {
                                return Err(TestCaseError::fail(
                                    "inactive PG acquired a payload lease",
                                ));
                            }
                            Err(err) => err,
                        };
                        let expected = matches!(
                            err,
                            StoreError::PgNotActive {
                                pg_id: 0,
                                cluster_epoch,
                                state,
                            } if cluster_epoch == current_epoch && state == pg_state
                        );
                        prop_assert!(expected, "unexpected inactive lease acquire error: {err:?}");
                        continue;
                    }
                    let lease = cluster
                        .acquire_object_payload_lease(&bucket, &key, generation_id)
                        .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
                    prop_assert_eq!(
                        cluster.object_payload_lease_count(&bucket, &key, generation_id),
                        1
                    );
                    drop(cluster);

                    current_epoch = ClusterEpoch::new(current_epoch.get() + 1).unwrap();
                    visited_epochs.insert(current_epoch);
                    set_trace_epoch(&mut map, current_epoch);
                    let cluster = current_cluster(&map);
                    prop_assert_eq!(
                        cluster.object_payload_lease_count(&bucket, &key, generation_id),
                        1
                    );
                    let released = lease.release();
                    prop_assert_eq!(released.remaining(), 0);
                    prop_assert_eq!(
                        cluster.object_payload_lease_count(&bucket, &key, generation_id),
                        0
                    );
                }
                LocalClusterTraceOp::RecoverAfterPhysicalShardLoss(seed) => {
                    if pg_state != PgState::Active {
                        continue;
                    }
                    let cluster = current_cluster(&map);
                    let payload = format!("recoverable-physical-shard-loss-{step}-{seed}");
                    let segment = write_committed_direct_segment(&cluster, payload.as_bytes());
                    let shard_path = cluster
                        .test_payload_shard_file_path(
                            segment.written.data_pg_id,
                            segment.written.ec,
                            &segment.segment_okh,
                            segment.generation_id,
                            0,
                        )
                        .unwrap();
                    std::fs::remove_file(shard_path).unwrap();

                    let mut recovered = Vec::new();
                    cluster
                        .read_segment_payload_stored_bytes_into(
                            crate::SegmentStoredBytesRequest {
                                data_pg_id: segment.written.data_pg_id,
                                segment_okh: segment.segment_okh,
                                segment_vid: segment.generation_id,
                                stored_size: segment.payload.len(),
                                segment_crc64: Some(checksum::crc64::checksum(&segment.payload)),
                                ec: segment.written.ec,
                            },
                            &mut recovered,
                        )
                        .unwrap();
                    prop_assert_eq!(recovered, segment.payload);
                }
                LocalClusterTraceOp::DrainPendingCreateBucketFromSecondHandle(seed) => {
                    if pg_state != PgState::Active || current_epoch != ClusterEpoch::INITIAL {
                        continue;
                    }
                    let pg_id = PgId::new(0);
                    let pending_bucket = trace_bucket_for_pg(
                        &map,
                        pg_id.get(),
                        &format!("trace-pending-create-{step}-{seed}-"),
                    );
                    let requested_bucket = trace_bucket_for_pg(
                        &map,
                        pg_id.get(),
                        &format!("trace-request-create-{step}-{seed}-"),
                    );
                    let primary = map
                        .metadata_pg_primary_node(current_epoch, pg_id)
                        .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
                    let primary_pg = primary
                        .storage_node()
                        .get_pg(pg_id.get())
                        .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
                    if primary_pg
                        .pending_metadata_command_slot(primary.node_id().as_u32(), current_epoch)
                        .map_err(|err| TestCaseError::fail(format!("{err:?}")))?
                        .is_some()
                    {
                        continue;
                    }
                    let log_index = primary_pg
                        .max_metadata_command_log_index(current_epoch)
                        .map_err(|err| TestCaseError::fail(format!("{err:?}")))?
                        + 1;
                    let pending_command =
                        create_bucket_metadata_command(pg_id, log_index, pending_bucket.clone());
                    primary_pg
                        .try_insert_pending_metadata_command_slot(
                            primary.node_id().as_u32(),
                            &pending_command,
                            Some(&pending_bucket),
                        )
                        .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
                    drop(primary_pg);

                    let second_handle = current_cluster(&map);
                    create_test_bucket(&second_handle, &requested_bucket);
                    for node_id in trace_node_ids() {
                        let pg = map
                            .node(node_id)
                            .unwrap()
                            .storage_node()
                            .get_pg(pg_id.get())
                            .unwrap();
                        crate::PgMetadataStore::head_bucket(&*pg, &pending_bucket).unwrap();
                        crate::PgMetadataStore::head_bucket(&*pg, &requested_bucket).unwrap();
                    }
                }
                LocalClusterTraceOp::RestartAndValidate => {
                    if pg_state != PgState::Active || current_epoch != ClusterEpoch::INITIAL {
                        continue;
                    }
                    map = Arc::new(
                        LocalClusterMap::open(tmp.path(), &node_ids, &[0], ec_shape)
                            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?,
                    );
                    assert_clean_metadata_command_stream(&map, &[0]);
                }
                LocalClusterTraceOp::ReissueDuplicateCreateBucketIndex(seed) => {
                    if pg_state != PgState::Active || current_epoch != ClusterEpoch::INITIAL {
                        continue;
                    }
                    let pg_id = PgId::new(0);
                    let first_bucket = trace_bucket_for_pg(
                        &map,
                        pg_id.get(),
                        &format!("trace-reissue-first-{step}-{seed}-"),
                    );
                    let second_bucket = trace_bucket_for_pg(
                        &map,
                        pg_id.get(),
                        &format!("trace-reissue-second-{step}-{seed}-"),
                    );
                    let cluster = current_cluster(&map);
                    let primary = map
                        .metadata_pg_primary_node(current_epoch, pg_id)
                        .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
                    let primary_pg = primary
                        .storage_node()
                        .get_pg(pg_id.get())
                        .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
                    if primary_pg
                        .pending_metadata_command_slot(primary.node_id().as_u32(), current_epoch)
                        .map_err(|err| TestCaseError::fail(format!("{err:?}")))?
                        .is_some()
                    {
                        continue;
                    }
                    let duplicate_index = primary_pg
                        .max_metadata_command_log_index(current_epoch)
                        .map_err(|err| TestCaseError::fail(format!("{err:?}")))?
                        + 1;
                    drop(primary_pg);

                    let applied = create_bucket_metadata_command(
                        pg_id,
                        duplicate_index,
                        first_bucket.clone(),
                    );
                    cluster
                        .test_apply_metadata_command_to_acting_set_from_origin(
                            primary.node_id(),
                            &applied,
                        )
                        .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
                    let stale_duplicate = create_bucket_metadata_command(
                        pg_id,
                        duplicate_index,
                        second_bucket.clone(),
                    );
                    let reissued = MetadataCommandEnvelope::new(
                        MetadataCommandId::new(
                            current_epoch,
                            pg_id,
                            MetadataCommandLogIndex::new(duplicate_index + 1)
                                .expect("trace duplicate index should not overflow"),
                        ),
                        stale_duplicate.payload().clone(),
                    );
                    force_insert_pending_metadata_command_for_test(
                        &map,
                        pg_id,
                        &second_bucket,
                        &stale_duplicate,
                    );

                    create_test_bucket(&cluster, &second_bucket);
                    for node_id in trace_node_ids() {
                        let pg = map
                            .node(node_id)
                            .unwrap()
                            .storage_node()
                            .get_pg(pg_id.get())
                            .unwrap();
                        crate::PgMetadataStore::head_bucket(&*pg, &first_bucket).unwrap();
                        crate::PgMetadataStore::head_bucket(&*pg, &second_bucket).unwrap();
                        let (command_checksum, command_bytes, abandoned): (i64, Vec<u8>, i64) = pg
                            .connection()
                            .query_row(
                                "SELECT command_checksum, command_bytes, abandoned \
                                 FROM metadata_command_log \
                                 WHERE cluster_epoch = ?1 AND pg_id = ?2 AND log_index = ?3",
                                rusqlite::params![
                                    current_epoch.get() as i64,
                                    pg_id.get() as i64,
                                    duplicate_index as i64 + 1,
                                ],
                                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
                            )
                            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
                        prop_assert_eq!(abandoned, 0);
                        prop_assert_eq!(command_checksum as u64, reissued.checksum_crc64());
                        prop_assert_eq!(command_bytes, reissued.command_bytes());
                    }
                    assert_clean_metadata_command_stream(&map, &[0]);
                }
            }
        }

        let trace_pg_ids = [PgId::new(0)];
        for epoch in visited_epochs.iter().copied() {
            assert_no_pending_metadata_command_slots_at_epoch(&map, &trace_pg_ids, epoch);
        }
        if visited_epochs.len() == 1 {
            assert_clean_metadata_command_stream(&map, &[0]);
        }
        Ok(())
    }

    proptest! {
        #![proptest_config(ProptestConfig {
            cases: 32,
            .. ProptestConfig::default()
        })]

        #[test]
        fn prop_local_cluster_trace_preserves_epoch_route_and_cleanup_invariants(
            ops in local_cluster_trace_strategy()
        ) {
            run_local_cluster_trace(&ops)?;
        }
    }

    #[derive(Debug, Clone)]
    enum MultipartTraceOp {
        Create { slot_seed: u8, key_seed: u8 },
        UploadStreamPart { slot_seed: u8, payload_seed: u8 },
        UploadCopiedPart { slot_seed: u8, payload_seed: u8 },
        Complete { slot_seed: u8 },
        Abort { slot_seed: u8 },
        DeleteRecreateBucket,
        StaleCreate { slot_seed: u8, key_seed: u8 },
        StaleUploadPartCreate { slot_seed: u8, payload_seed: u8 },
        StaleAbort { slot_seed: u8 },
        Reopen,
    }

    #[derive(Debug)]
    struct MultipartTraceUpload {
        upload_id: crate::UploadId,
        key: crate::ObjectKey,
        object_pg: u32,
        next_part_number: u32,
        parts: Vec<crate::MultipartPartRecord>,
    }

    fn multipart_trace_strategy() -> impl Strategy<Value = Vec<MultipartTraceOp>> {
        prop::collection::vec(
            prop_oneof![
                3 => (any::<u8>(), any::<u8>()).prop_map(|(slot_seed, key_seed)| {
                    MultipartTraceOp::Create { slot_seed, key_seed }
                }),
                3 => (any::<u8>(), any::<u8>()).prop_map(|(slot_seed, payload_seed)| {
                    MultipartTraceOp::UploadStreamPart { slot_seed, payload_seed }
                }),
                2 => (any::<u8>(), any::<u8>()).prop_map(|(slot_seed, payload_seed)| {
                    MultipartTraceOp::UploadCopiedPart { slot_seed, payload_seed }
                }),
                2 => any::<u8>().prop_map(|slot_seed| MultipartTraceOp::Complete { slot_seed }),
                2 => any::<u8>().prop_map(|slot_seed| MultipartTraceOp::Abort { slot_seed }),
                1 => Just(MultipartTraceOp::DeleteRecreateBucket),
                1 => (any::<u8>(), any::<u8>()).prop_map(|(slot_seed, key_seed)| {
                    MultipartTraceOp::StaleCreate { slot_seed, key_seed }
                }),
                1 => (any::<u8>(), any::<u8>()).prop_map(|(slot_seed, payload_seed)| {
                    MultipartTraceOp::StaleUploadPartCreate { slot_seed, payload_seed }
                }),
                1 => any::<u8>().prop_map(|slot_seed| MultipartTraceOp::StaleAbort { slot_seed }),
                1 => Just(MultipartTraceOp::Reopen),
            ],
            1..=16,
        )
    }

    fn multipart_trace_upload_id(step: usize, seed: u8) -> crate::UploadId {
        upload_id_from_label(&format!("trmpu{step:02x}{seed:02x}"))
    }

    fn multipart_trace_slot(seed: u8) -> usize {
        usize::from(seed % 3)
    }

    fn create_multipart_trace_upload(
        cluster: &crate::StorageCluster,
        bucket: &crate::BucketName,
        key: &crate::ObjectKey,
        upload_id: crate::UploadId,
    ) -> TestCaseResult {
        let create = crate::CreateMultipartUploadReq {
            upload_id,
            bucket: bucket.clone(),
            key: key.clone(),
            tags: None,
            metadata_blob: crate::SerializedMetadataBlob::default(),
            system_metadata_blob: crate::SerializedSystemMetadataBlob::default(),
            initiator: Some(crate::OwnerIdentity::from_principal("initiator")),
            owner: crate::OwnerIdentity::from_principal("owner"),
            acl_grants: crate::AclGrants::default(),
            public_read: false,
            object_lock: crate::ObjectLockState::default(),
            checksum: None,
            encryption: crate::ObjectEncryption::None,
        };
        cluster
            .create_multipart_upload(
                bucket,
                key,
                crate::BucketSnapshotRequest::default(),
                |_snapshot, _existing_object| Ok::<_, ()>(((), create.clone())),
            )
            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?
            .map_err(|_| TestCaseError::fail("multipart trace create action failed"))?;
        Ok(())
    }

    fn stale_multipart_trace_cluster(map: &Arc<LocalClusterMap>) -> Arc<crate::StorageCluster> {
        crate::StorageCluster::test_from_local_map_with_epoch(
            Arc::clone(map),
            ClusterEpoch::new(2).unwrap(),
        )
        .unwrap()
    }

    fn assert_multipart_trace_stale_snapshot_error(
        err: crate::BucketSnapshotLoadError,
    ) -> TestCaseResult {
        prop_assert!(
            matches!(
                err,
                crate::BucketSnapshotLoadError::Store(StoreError::StaleMetadataOperation {
                    operation_epoch,
                    current_epoch,
                    ..
                }) if operation_epoch == ClusterEpoch::new(2).unwrap()
                    && current_epoch == ClusterEpoch::INITIAL
            ),
            "unexpected stale multipart snapshot error: {err:?}"
        );
        Ok(())
    }

    fn assert_multipart_trace_stale_object_pg_error(
        err: crate::ObjectPgActionError,
    ) -> TestCaseResult {
        prop_assert!(
            matches!(
                err,
                crate::ObjectPgActionError::Store(StoreError::StaleMetadataOperation {
                    operation_epoch,
                    current_epoch,
                    ..
                }) if operation_epoch == ClusterEpoch::new(2).unwrap()
                    && current_epoch == ClusterEpoch::INITIAL
            ),
            "unexpected stale multipart object-PG error: {err:?}"
        );
        Ok(())
    }

    fn stale_create_multipart_trace_upload(
        cluster: &crate::StorageCluster,
        stale_cluster: &crate::StorageCluster,
        bucket: &crate::BucketName,
        key: &crate::ObjectKey,
        upload_id: crate::UploadId,
    ) -> TestCaseResult {
        let create = crate::CreateMultipartUploadReq {
            upload_id: upload_id.clone(),
            bucket: bucket.clone(),
            key: key.clone(),
            tags: None,
            metadata_blob: crate::SerializedMetadataBlob::default(),
            system_metadata_blob: crate::SerializedSystemMetadataBlob::default(),
            initiator: Some(crate::OwnerIdentity::from_principal("initiator")),
            owner: crate::OwnerIdentity::from_principal("owner"),
            acl_grants: crate::AclGrants::default(),
            public_read: false,
            object_lock: crate::ObjectLockState::default(),
            checksum: None,
            encryption: crate::ObjectEncryption::None,
        };
        let err = stale_cluster
            .create_multipart_upload(
                bucket,
                key,
                crate::BucketSnapshotRequest::default(),
                |_snapshot, _existing_object| Ok::<_, ()>(((), create.clone())),
            )
            .unwrap_err();
        assert_multipart_trace_stale_snapshot_error(err)?;
        let err = cluster
            .load_multipart_upload(bucket, key, &upload_id)
            .unwrap_err();
        prop_assert!(
            matches!(
                err,
                crate::BucketSnapshotLoadError::Metadata(crate::MetadataError::NoSuchUpload { .. })
            ),
            "stale create mutated upload state: {err:?}"
        );
        Ok(())
    }

    fn stale_create_upload_part_stream_session(
        cluster: &crate::StorageCluster,
        stale_cluster: &crate::StorageCluster,
        map: &LocalClusterMap,
        bucket: &crate::BucketName,
        upload: &MultipartTraceUpload,
        session_id: crate::SessionId,
    ) -> TestCaseResult {
        let upload_row = cluster
            .load_in_progress_multipart_upload(bucket, &upload.key, &upload.upload_id)
            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
        let err = stale_cluster
            .create_upload_part_stream_session(
                &crate::AuthorizedMultipartUploadRecord::assume_authorized(upload_row),
                upload.next_part_number,
                &session_id,
            )
            .unwrap_err();
        assert_multipart_trace_stale_object_pg_error(err)?;
        cluster
            .load_in_progress_multipart_upload(bucket, &upload.key, &upload.upload_id)
            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
        for node_id in map.node_ids() {
            let pg = map
                .node(node_id)
                .unwrap()
                .storage_node()
                .get_pg(upload.object_pg)
                .unwrap();
            prop_assert!(
                matches!(
                    crate::PgMetadataStore::get_stream_upload(&*pg, &session_id),
                    Err(crate::MetadataError::StreamSessionNotFound { .. })
                ),
                "stale UploadPart session create inserted stream_uploads row on node {node_id:?}"
            );
            let segments = crate::PgMetadataStore::list_stream_segments(&*pg, &session_id)
                .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
            prop_assert!(
                segments.is_empty(),
                "stale UploadPart session create inserted stream segments on node {node_id:?}: {segments:?}"
            );
        }
        Ok(())
    }

    #[derive(Debug, PartialEq, Eq)]
    struct MultipartTraceUploadSnapshot {
        upload_exists: bool,
        parts: Vec<crate::MultipartPartRecord>,
        part_segments: Vec<crate::MultipartPartSegmentRecord>,
        stream_sessions: Vec<(
            crate::StreamUploadRecord,
            Vec<crate::StreamUploadSegmentRecord>,
        )>,
    }

    fn multipart_trace_upload_snapshot(
        map: &LocalClusterMap,
        node_id: NodeId,
        upload: &MultipartTraceUpload,
    ) -> MultipartTraceUploadSnapshot {
        let pg = map
            .node(node_id)
            .unwrap()
            .storage_node()
            .get_pg(upload.object_pg)
            .unwrap();
        let upload_exists =
            crate::PgMetadataStore::get_multipart_upload(&*pg, &upload.upload_id).is_ok();
        let parts = if upload_exists {
            crate::PgMetadataStore::list_multipart_parts(
                &*pg,
                &crate::ListPartsReq {
                    upload_id: upload.upload_id.clone(),
                    part_number_marker: None,
                    max_parts: 1000,
                },
            )
            .unwrap()
            .parts
        } else {
            Vec::new()
        };
        let part_segments = crate::PgMetadataStore::get_all_multipart_part_segments_for_upload(
            &*pg,
            &upload.upload_id,
        )
        .unwrap();
        let mut stream_sessions = crate::PgMetadataStore::list_all_stream_uploads(&*pg)
            .unwrap()
            .into_iter()
            .filter(|session| {
                matches!(
                    &session.target,
                    crate::StreamUploadTarget::UploadPart {
                        upload_id: session_upload_id,
                        ..
                    } if session_upload_id == &upload.upload_id
                )
            })
            .map(|session| {
                let segments =
                    crate::PgMetadataStore::list_stream_segments(&*pg, &session.session_id)
                        .unwrap();
                (session, segments)
            })
            .collect::<Vec<_>>();
        stream_sessions.sort_by(|(left, _), (right, _)| {
            left.session_id.as_str().cmp(right.session_id.as_str())
        });
        MultipartTraceUploadSnapshot {
            upload_exists,
            parts,
            part_segments,
            stream_sessions,
        }
    }

    fn multipart_trace_upload_snapshots(
        map: &LocalClusterMap,
        upload: &MultipartTraceUpload,
    ) -> BTreeMap<u32, MultipartTraceUploadSnapshot> {
        map.node_ids()
            .map(|node_id| {
                (
                    node_id.as_u32(),
                    multipart_trace_upload_snapshot(map, node_id, upload),
                )
            })
            .collect()
    }

    fn stale_abort_multipart_trace_upload(
        cluster: &crate::StorageCluster,
        stale_cluster: &crate::StorageCluster,
        map: &LocalClusterMap,
        bucket: &crate::BucketName,
        upload: &MultipartTraceUpload,
    ) -> TestCaseResult {
        let before = multipart_trace_upload_snapshots(map, upload);
        let err = stale_cluster
            .abort_multipart_upload(bucket, &upload.key, &upload.upload_id)
            .unwrap_err();
        assert_multipart_trace_stale_object_pg_error(err)?;
        cluster
            .load_in_progress_multipart_upload(bucket, &upload.key, &upload.upload_id)
            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
        let after = multipart_trace_upload_snapshots(map, upload);
        prop_assert_eq!(
            after,
            before,
            "stale abort changed multipart upload parts or stream-session state"
        );
        Ok(())
    }

    fn upload_copied_test_multipart_part(
        cluster: &crate::StorageCluster,
        bucket: &crate::BucketName,
        key: &crate::ObjectKey,
        upload_id: &crate::UploadId,
        part_number: u32,
        payload_seed: u8,
        payloads: [&[u8]; 2],
    ) -> crate::MultipartPartRecord {
        let session_seed = payload_seed.max(1);
        let session_id =
            crate::SessionId::try_from(format!("{session_seed:02x}").repeat(16)).unwrap();
        let upload = cluster
            .load_in_progress_multipart_upload(bucket, key, upload_id)
            .unwrap();
        cluster
            .create_upload_part_stream_session(
                &crate::AuthorizedMultipartUploadRecord::assume_authorized(upload),
                part_number,
                &session_id,
            )
            .unwrap();

        let mut staged_segments = Vec::new();
        for (segment_index, payload) in payloads.into_iter().enumerate() {
            let segment_okh = [payload_seed
                .wrapping_add(u8::try_from(segment_index).unwrap())
                .max(1); 16];
            let (_target, segment) = cluster
                .prepare_stream_segment_append(
                    bucket,
                    key,
                    &crate::PrepareStreamUploadSegmentAppendReq {
                        session_id: session_id.clone(),
                        segment_index: u32::try_from(segment_index).unwrap(),
                        size: payload.len() as u64,
                        segment_crc64: Some(checksum::crc64::checksum(payload)),
                        segment_okh,
                    },
                )
                .unwrap();
            let written_shards = cluster
                .write_stream_segment_payload_shards(&segment, payload)
                .unwrap();
            let shard_batch = written_shards
                .iter()
                .map(|written| (&written.key, written.ack))
                .collect::<Vec<_>>();
            cluster
                .commit_stream_segment_append(
                    bucket,
                    key,
                    &session_id,
                    segment.segment_index,
                    &segment,
                    &shard_batch,
                )
                .unwrap();
            staged_segments.push(segment);
        }

        let size = payloads.iter().map(|payload| payload.len() as u64).sum();
        let part = cluster
            .finalize_upload_part_stream(
                bucket,
                key,
                upload_id,
                &session_id,
                part_number,
                |snapshot| {
                    let generation = snapshot
                        .existing_part_generation
                        .map_or(0, |generation| generation + 1);
                    let ec = snapshot
                        .staging_segments
                        .first()
                        .map(|segment| EcShape {
                            k: segment.ec_k,
                            m: segment.ec_m,
                        })
                        .unwrap_or(EcShape { k: 0, m: 0 });
                    let part = crate::MultipartPartRecord {
                        upload_id: upload_id.clone(),
                        part_number,
                        generation,
                        size,
                        etag: vec![payload_seed; 8],
                        etag_kind: crate::EtagKind::Crc64,
                        part_okh: [0u8; 16],
                        part_vid: crate::GenerationId::new(u64::from(generation) + 1).unwrap(),
                        ec_k: ec.k,
                        ec_m: ec.m,
                        last_modified: 123,
                        checksum: None,
                    };
                    let segments = snapshot
                        .staging_segments
                        .iter()
                        .map(|staged| crate::MultipartPartSegmentRecord {
                            bucket: bucket.clone(),
                            key: key.clone(),
                            upload_id: upload_id.clone(),
                            version_id: crate::MULTIPART_PART_SEGMENT_STAGING_VERSION_ID.to_u64(),
                            part_number,
                            segment_index: staged.segment_index,
                            size: staged.size,
                            segment_crc64: staged.segment_crc64,
                            segment_okh: staged.segment_okh,
                            segment_vid: staged.segment_vid,
                            data_pg_id: staged.data_pg_id,
                            ec_k: staged.ec_k,
                            ec_m: staged.ec_m,
                        })
                        .collect::<Vec<_>>();
                    Ok::<_, ()>(crate::PreparedStreamPartCommit {
                        value: part.clone(),
                        part,
                        segments,
                    })
                },
            )
            .unwrap()
            .unwrap()
            .value;
        assert_eq!(staged_segments.len(), 2);
        part
    }

    fn complete_multipart_trace_upload(
        cluster: &crate::StorageCluster,
        map: &LocalClusterMap,
        node_ids: &[NodeId],
        bucket: &crate::BucketName,
        upload: &MultipartTraceUpload,
    ) -> TestCaseResult {
        if upload.parts.is_empty() {
            return Ok(());
        }
        let upload_row = cluster
            .load_in_progress_multipart_upload(bucket, &upload.key, &upload.upload_id)
            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
        let size = upload.parts.iter().map(|part| part.size).sum();
        cluster
            .complete_multipart_upload_commit_serialized(
                crate::CompleteMultipartCommitRequest {
                    bucket: bucket.clone(),
                    key: upload.key.clone(),
                    upload_id: upload.upload_id.clone(),
                    versioning: crate::BucketVersioningState::Disabled,
                    owner: upload_row.owner,
                    acl_grants: upload_row.acl_grants,
                    public_read: upload_row.public_read,
                    generation_id: upload_row.object_generation_id,
                    size,
                    etag_crc64: [0x51; 8],
                    tags: upload_row.tags,
                    metadata_blob: Some(upload_row.metadata_blob),
                    system_metadata_blob: Some(upload_row.system_metadata_blob),
                    object_lock: upload_row.object_lock,
                    encryption: upload_row.encryption,
                    part_records: upload.parts.clone(),
                },
                16,
            )
            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
        assert_terminal_multipart_upload_invariants(
            map,
            node_ids,
            upload.object_pg,
            bucket,
            &upload.key,
            &upload.upload_id,
            TerminalMultipartOutcome::Completed,
        );
        assert_clean_metadata_command_stream(map, &[1, upload.object_pg]);
        Ok(())
    }

    fn abort_multipart_trace_upload(
        cluster: &crate::StorageCluster,
        map: &LocalClusterMap,
        node_ids: &[NodeId],
        bucket: &crate::BucketName,
        upload: &MultipartTraceUpload,
    ) -> TestCaseResult {
        cluster
            .abort_multipart_upload(bucket, &upload.key, &upload.upload_id)
            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
        assert_terminal_multipart_upload_invariants(
            map,
            node_ids,
            upload.object_pg,
            bucket,
            &upload.key,
            &upload.upload_id,
            TerminalMultipartOutcome::Aborted,
        );
        assert_clean_metadata_command_stream(map, &[upload.object_pg]);
        Ok(())
    }

    fn delete_recreate_multipart_trace_bucket(
        cluster: &crate::StorageCluster,
        map: &LocalClusterMap,
        bucket: &crate::BucketName,
    ) -> TestCaseResult {
        cluster
            .begin_bucket_delete(bucket)
            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
        let outcome = cluster
            .try_finalize_bucket_delete(bucket)
            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
        prop_assert_eq!(outcome, crate::BucketDeleteFinalizeOutcome::Finalized);
        assert_clean_metadata_command_stream(map, &[1]);
        create_test_bucket(cluster, bucket);
        assert_clean_metadata_command_stream(map, &[1]);
        Ok(())
    }

    fn run_multipart_trace(ops: &[MultipartTraceOp]) -> TestCaseResult {
        let tmp = test_util::tempdir();
        let node_ids = [NodeId::new(0), NodeId::new(1), NodeId::new(2)];
        let pg_ids = [0, 1, 2, 3];
        let ec_shape = EcShape { k: 2, m: 1 };
        let mut initial_map = LocalClusterMap::open(tmp.path(), &node_ids, &pg_ids, ec_shape)
            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
        let topology = initial_map
            .node(NodeId::new(0))
            .unwrap()
            .storage_node()
            .pg_topology();
        let bucket = bucket_for_pg(topology, 1, "mpu-trace-");
        let keys = [
            (key_for_object_pg(topology, &bucket, 2, "object-a-"), 2_u32),
            (key_for_object_pg(topology, &bucket, 3, "object-b-"), 3_u32),
        ];
        set_route_primary(&mut initial_map, 1, NodeId::new(1));
        set_route_primary(&mut initial_map, 2, NodeId::new(1));
        set_route_primary(&mut initial_map, 3, NodeId::new(2));

        let mut map = Arc::new(initial_map);
        let mut cluster = crate::StorageCluster::from_local_map(Arc::clone(&map))
            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
        create_test_bucket(&cluster, &bucket);

        let mut active_uploads: [Option<MultipartTraceUpload>; 3] = [None, None, None];
        let mut completed_object_exists = false;
        for (step, op) in ops.iter().enumerate() {
            match op {
                MultipartTraceOp::Create {
                    slot_seed,
                    key_seed,
                } => {
                    let slot = multipart_trace_slot(*slot_seed);
                    if active_uploads[slot].is_some() {
                        continue;
                    }
                    let (key, object_pg) = &keys[usize::from(*key_seed % 2)];
                    let upload_id = multipart_trace_upload_id(step, *slot_seed);
                    create_multipart_trace_upload(&cluster, &bucket, key, upload_id.clone())?;
                    active_uploads[slot] = Some(MultipartTraceUpload {
                        upload_id,
                        key: key.clone(),
                        object_pg: *object_pg,
                        next_part_number: 1,
                        parts: Vec::new(),
                    });
                }
                MultipartTraceOp::UploadStreamPart {
                    slot_seed,
                    payload_seed,
                } => {
                    let Some(upload) = active_uploads[multipart_trace_slot(*slot_seed)].as_mut()
                    else {
                        continue;
                    };
                    if upload.next_part_number > 3 {
                        continue;
                    }
                    let segment_seed = payload_seed.wrapping_add(step as u8).max(1);
                    let payload = format!("multipart trace payload {step} {payload_seed}");
                    let (_shard_keys, part, _segment) = upload_streamed_test_multipart_part(
                        &cluster,
                        &bucket,
                        &upload.key,
                        &upload.upload_id,
                        upload.next_part_number,
                        [segment_seed; 16],
                        payload.as_bytes(),
                    );
                    upload.parts.push(part);
                    upload.next_part_number += 1;
                }
                MultipartTraceOp::UploadCopiedPart {
                    slot_seed,
                    payload_seed,
                } => {
                    let Some(upload) = active_uploads[multipart_trace_slot(*slot_seed)].as_mut()
                    else {
                        continue;
                    };
                    if upload.next_part_number > 3 {
                        continue;
                    }
                    let first_payload = format!("copied trace payload {step} {payload_seed} a");
                    let second_payload = format!("copied trace payload {step} {payload_seed} b");
                    let part = upload_copied_test_multipart_part(
                        &cluster,
                        &bucket,
                        &upload.key,
                        &upload.upload_id,
                        upload.next_part_number,
                        payload_seed.wrapping_add(step as u8).max(1),
                        [first_payload.as_bytes(), second_payload.as_bytes()],
                    );
                    upload.parts.push(part);
                    upload.next_part_number += 1;
                }
                MultipartTraceOp::Complete { slot_seed } => {
                    let slot = multipart_trace_slot(*slot_seed);
                    let Some(upload) = active_uploads[slot].take() else {
                        continue;
                    };
                    if upload.parts.is_empty() {
                        active_uploads[slot] = Some(upload);
                        continue;
                    }
                    complete_multipart_trace_upload(&cluster, &map, &node_ids, &bucket, &upload)?;
                    completed_object_exists = true;
                }
                MultipartTraceOp::Abort { slot_seed } => {
                    let slot = multipart_trace_slot(*slot_seed);
                    let Some(upload) = active_uploads[slot].take() else {
                        continue;
                    };
                    abort_multipart_trace_upload(&cluster, &map, &node_ids, &bucket, &upload)?;
                }
                MultipartTraceOp::DeleteRecreateBucket => {
                    if completed_object_exists || active_uploads.iter().any(Option::is_some) {
                        continue;
                    }
                    delete_recreate_multipart_trace_bucket(&cluster, &map, &bucket)?;
                }
                MultipartTraceOp::StaleCreate {
                    slot_seed,
                    key_seed,
                } => {
                    let stale_cluster = stale_multipart_trace_cluster(&map);
                    let (key, _) = &keys[usize::from(*key_seed % 2)];
                    let upload_id = multipart_trace_upload_id(step, *slot_seed);
                    stale_create_multipart_trace_upload(
                        &cluster,
                        &stale_cluster,
                        &bucket,
                        key,
                        upload_id,
                    )?;
                }
                MultipartTraceOp::StaleUploadPartCreate {
                    slot_seed,
                    payload_seed,
                } => {
                    let Some(upload) = active_uploads[multipart_trace_slot(*slot_seed)].as_ref()
                    else {
                        continue;
                    };
                    let stale_cluster = stale_multipart_trace_cluster(&map);
                    let session_id = trace_session(payload_seed.wrapping_add(step as u8));
                    stale_create_upload_part_stream_session(
                        &cluster,
                        &stale_cluster,
                        &map,
                        &bucket,
                        upload,
                        session_id,
                    )?;
                }
                MultipartTraceOp::StaleAbort { slot_seed } => {
                    let Some(upload) = active_uploads[multipart_trace_slot(*slot_seed)].as_ref()
                    else {
                        continue;
                    };
                    let stale_cluster = stale_multipart_trace_cluster(&map);
                    stale_abort_multipart_trace_upload(
                        &cluster,
                        &stale_cluster,
                        &map,
                        &bucket,
                        upload,
                    )?;
                }
                MultipartTraceOp::Reopen => {
                    drop(cluster);
                    drop(map);
                    let mut reopened =
                        LocalClusterMap::open(tmp.path(), &node_ids, &pg_ids, ec_shape)
                            .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
                    set_route_primary(&mut reopened, 1, NodeId::new(1));
                    set_route_primary(&mut reopened, 2, NodeId::new(1));
                    set_route_primary(&mut reopened, 3, NodeId::new(2));
                    map = Arc::new(reopened);
                    cluster = crate::StorageCluster::from_local_map(Arc::clone(&map))
                        .map_err(|err| TestCaseError::fail(format!("{err:?}")))?;
                    assert_clean_metadata_command_stream(&map, &[1, 2, 3]);
                }
            }
        }

        for upload in active_uploads.into_iter().flatten() {
            abort_multipart_trace_upload(&cluster, &map, &node_ids, &bucket, &upload)?;
        }
        assert_clean_metadata_command_stream(&map, &[1, 2, 3]);
        Ok(())
    }

