    #[test]
    fn metadata_command_log_index_allocator_drains_unresolved_durable_pending_slot() {
        let tmp = test_util::tempdir();
        let node_ids = [NodeId::new(0), NodeId::new(1), NodeId::new(2)];
        let ec_shape = EcShape { k: 2, m: 1 };
        let mut map = LocalClusterMap::open(tmp.path(), &node_ids, &[0, 1], ec_shape).unwrap();
        let topology = map
            .node(NodeId::new(0))
            .unwrap()
            .storage_node()
            .pg_topology();
        let pending_bucket = bucket_for_pg(topology, 1, "durable-pending-first-");
        let blocked_bucket = bucket_for_pg(topology, 1, "durable-pending-second-");
        set_route_primary(&mut map, 1, NodeId::new(1));
        let map = Arc::new(map);
        let cluster = crate::StorageCluster::from_local_map(Arc::clone(&map)).unwrap();
        let pg_id = PgId::new(1);
        let pending = create_bucket_metadata_command(pg_id, 1, pending_bucket.clone());
        {
            let primary_pg = map
                .node(NodeId::new(1))
                .unwrap()
                .storage_node()
                .get_pg(1)
                .unwrap();
            primary_pg
                .try_insert_pending_metadata_command_slot(
                    NodeId::new(1).as_u32(),
                    &pending,
                    Some(&pending_bucket),
                )
                .unwrap();
        }

        let owner = crate::CanonicalUserId::from_principal("owner");
        let acl_grants = crate::AclGrants::default();
        cluster
            .create_bucket_with_config_and_load_info(&crate::CreateBucketConfig {
                name: blocked_bucket.as_str(),
                owner_principal: "owner",
                owner_canonical_id: &owner,
                acl_grants: &acl_grants,
                public_read: false,
                public_write: false,
                versioning: crate::BucketVersioningState::Disabled,
                object_lock: crate::BucketObjectLockConfig::default(),
            })
            .unwrap();

        for node_id in node_ids {
            let pg = map.node(node_id).unwrap().storage_node().get_pg(1).unwrap();
            assert_eq!(
                pg.max_metadata_command_log_index(ClusterEpoch::INITIAL)
                    .unwrap(),
                2
            );
            assert_eq!(
                pg.metadata_command_replica_state()
                    .unwrap()
                    .applied_log_index,
                2
            );
            crate::PgMetadataStore::head_bucket(&*pg, &pending_bucket).unwrap();
            crate::PgMetadataStore::head_bucket(&*pg, &blocked_bucket).unwrap();
        }
        let primary_pg = map
            .node(NodeId::new(1))
            .unwrap()
            .storage_node()
            .get_pg(1)
            .unwrap();
        assert!(primary_pg
            .pending_metadata_command_slot(NodeId::new(1).as_u32(), ClusterEpoch::INITIAL)
            .unwrap()
            .is_none());
    }

    #[test]
    fn object_metadata_pending_install_race_drains_winner_and_retries() {
        let _guard = lock_metadata_command_apply_hook_test();
        let tmp = test_util::tempdir();
        let node_ids = [NodeId::new(0), NodeId::new(1), NodeId::new(2)];
        let pg_ids = [0, 1, 2, 3];
        let ec_shape = EcShape { k: 2, m: 1 };
        let mut first_map =
            LocalClusterMap::open(tmp.path(), &node_ids, &pg_ids, ec_shape).unwrap();
        let topology = first_map
            .node(NodeId::new(0))
            .unwrap()
            .storage_node()
            .pg_topology();
        let bucket = bucket_for_pg(topology, 1, "pending-install-race-");
        let first_key = key_for_object_pg(topology, &bucket, 2, "first-object-");
        let second_key = key_for_object_pg(topology, &bucket, 2, "second-object-");
        set_route_primary(&mut first_map, 1, NodeId::new(1));
        set_route_primary(&mut first_map, 2, NodeId::new(1));

        let mut second_map =
            LocalClusterMap::open(tmp.path(), &node_ids, &pg_ids, ec_shape).unwrap();
        set_route_primary(&mut second_map, 1, NodeId::new(1));
        set_route_primary(&mut second_map, 2, NodeId::new(1));

        let first_map = Arc::new(first_map);
        let second_map = Arc::new(second_map);
        let first_cluster = crate::StorageCluster::from_local_map(Arc::clone(&first_map)).unwrap();
        create_test_bucket(&first_cluster, &bucket);
        let first_committed = write_committed_direct_segment_for_with_okh(
            &first_cluster,
            &bucket,
            &first_key,
            [0x81; 16],
            b"first",
        );
        write_committed_direct_segment_for_with_okh(
            &first_cluster,
            &bucket,
            &second_key,
            [0x82; 16],
            b"second",
        );

        let hook_ran = Arc::new(AtomicBool::new(false));
        let hook_map = Arc::clone(&second_map);
        let hook_bucket = bucket.clone();
        let hook_key = second_key.clone();
        let hook_ran_for_closure = Arc::clone(&hook_ran);
        let second_tags =
            "<Tagging><TagSet><Tag><Key>slot</Key><Value>winner</Value></Tag></TagSet></Tagging>"
                .to_string();
        let hook_second_tags = second_tags.clone();
        let hook_proof = acquire_test_bucket_write_proof(
            &first_cluster,
            &bucket,
            "test-put-object-metadata-race",
            Some(second_key.as_str()),
        );
        let _hook_guard = first_cluster.test_install_before_metadata_command_pending_install_hook(
            Arc::new(move || {
                if hook_ran_for_closure.swap(true, Ordering::SeqCst) {
                    return;
                }
                let pg_id = PgId::new(2);
                let primary = hook_map
                    .metadata_pg_primary_node(ClusterEpoch::INITIAL, pg_id)
                    .unwrap();
                let pg = primary.storage_node().get_pg(pg_id.get()).unwrap();
                let stored =
                    crate::PgMetadataStore::get_object_meta(&*pg, &hook_bucket, &hook_key).unwrap();
                let live = stored.as_live().expect("test object is live").clone();
                let log_index = pg
                    .max_metadata_command_log_index(ClusterEpoch::INITIAL)
                    .unwrap()
                    + 1;
                let command = MetadataCommandEnvelope::new(
                    MetadataCommandId::new(
                        ClusterEpoch::INITIAL,
                        pg_id,
                        MetadataCommandLogIndex::new(log_index).unwrap(),
                    ),
                    MetadataCommandPayload::PutObjectMetadata(Box::new(
                        PutObjectMetadataCommand::from_live_object_and_mutation(
                            live,
                            PutObjectMetadataMutation::PutTags(hook_second_tags.clone()),
                            hook_proof.clone(),
                        ),
                    )),
                );
                pg.try_insert_pending_metadata_command_slot(
                    primary.node_id().as_u32(),
                    &command,
                    Some(&hook_bucket),
                )
                .unwrap();
            }),
        );

        let first_tags =
            "<Tagging><TagSet><Tag><Key>slot</Key><Value>retry</Value></Tag></TagSet></Tagging>";
        let tagged_version = first_cluster
            .put_object_tags_if(&bucket, &first_key, None, first_tags, |stored| {
                Ok::<_, ()>(stored.version_id())
            })
            .unwrap()
            .unwrap();
        assert_eq!(tagged_version, first_committed.version_id);
        assert!(hook_ran.load(Ordering::SeqCst));
        assert!(pending_metadata_command_for_test(&first_map, PgId::new(2), &bucket).is_none());

        for (key, tags) in [
            (&first_key, first_tags),
            (&second_key, second_tags.as_str()),
        ] {
            for node_id in node_ids {
                let pg = first_map
                    .node(node_id)
                    .unwrap()
                    .storage_node()
                    .get_pg(2)
                    .unwrap();
                let stored = crate::PgMetadataStore::get_object_meta(&*pg, &bucket, key).unwrap();
                let live = stored.as_live().expect("test object is live");
                assert_eq!(
                    live.tags.as_ref().map(crate::SerializedTagSet::as_str),
                    Some(tags)
                );
            }
        }
    }

    #[test]
    fn object_metadata_pending_install_race_reruns_precondition_action() {
        let _guard = lock_metadata_command_apply_hook_test();
        let tmp = test_util::tempdir();
        let node_ids = [NodeId::new(0), NodeId::new(1), NodeId::new(2)];
        let pg_ids = [0, 1, 2, 3];
        let ec_shape = EcShape { k: 2, m: 1 };
        let mut first_map =
            LocalClusterMap::open(tmp.path(), &node_ids, &pg_ids, ec_shape).unwrap();
        let topology = first_map
            .node(NodeId::new(0))
            .unwrap()
            .storage_node()
            .pg_topology();
        let bucket = bucket_for_pg(topology, 1, "pending-install-precondition-");
        let key = key_for_object_pg(topology, &bucket, 2, "object-");
        set_route_primary(&mut first_map, 1, NodeId::new(1));
        set_route_primary(&mut first_map, 2, NodeId::new(1));

        let mut second_map =
            LocalClusterMap::open(tmp.path(), &node_ids, &pg_ids, ec_shape).unwrap();
        set_route_primary(&mut second_map, 1, NodeId::new(1));
        set_route_primary(&mut second_map, 2, NodeId::new(1));

        let first_map = Arc::new(first_map);
        let second_map = Arc::new(second_map);
        let first_cluster = crate::StorageCluster::from_local_map(Arc::clone(&first_map)).unwrap();
        create_test_bucket(&first_cluster, &bucket);
        write_committed_direct_segment_for_with_okh(
            &first_cluster,
            &bucket,
            &key,
            [0x83; 16],
            b"object",
        );

        let hook_ran = Arc::new(AtomicBool::new(false));
        let action_calls = Arc::new(AtomicUsize::new(0));
        let hook_map = Arc::clone(&second_map);
        let hook_bucket = bucket.clone();
        let hook_key = key.clone();
        let hook_ran_for_closure = Arc::clone(&hook_ran);
        let winner_tags =
            "<Tagging><TagSet><Tag><Key>slot</Key><Value>winner</Value></Tag></TagSet></Tagging>"
                .to_string();
        let hook_winner_tags = winner_tags.clone();
        let hook_proof = acquire_test_bucket_write_proof(
            &first_cluster,
            &bucket,
            "test-put-object-metadata-race",
            Some(key.as_str()),
        );
        let _hook_guard = first_cluster.test_install_before_metadata_command_pending_install_hook(
            Arc::new(move || {
                if hook_ran_for_closure.swap(true, Ordering::SeqCst) {
                    return;
                }
                let pg_id = PgId::new(2);
                let primary = hook_map
                    .metadata_pg_primary_node(ClusterEpoch::INITIAL, pg_id)
                    .unwrap();
                let pg = primary.storage_node().get_pg(pg_id.get()).unwrap();
                let stored =
                    crate::PgMetadataStore::get_object_meta(&*pg, &hook_bucket, &hook_key).unwrap();
                let live = stored.as_live().expect("test object is live").clone();
                let log_index = pg
                    .max_metadata_command_log_index(ClusterEpoch::INITIAL)
                    .unwrap()
                    + 1;
                let command = MetadataCommandEnvelope::new(
                    MetadataCommandId::new(
                        ClusterEpoch::INITIAL,
                        pg_id,
                        MetadataCommandLogIndex::new(log_index).unwrap(),
                    ),
                    MetadataCommandPayload::PutObjectMetadata(Box::new(
                        PutObjectMetadataCommand::from_live_object_and_mutation(
                            live,
                            PutObjectMetadataMutation::PutTags(hook_winner_tags.clone()),
                            hook_proof.clone(),
                        ),
                    )),
                );
                pg.try_insert_pending_metadata_command_slot(
                    primary.node_id().as_u32(),
                    &command,
                    Some(&hook_bucket),
                )
                .unwrap();
            }),
        );

        let loser_tags =
            "<Tagging><TagSet><Tag><Key>slot</Key><Value>loser</Value></Tag></TagSet></Tagging>";
        let calls_for_action = Arc::clone(&action_calls);
        let result = first_cluster
            .put_object_tags_if(&bucket, &key, None, loser_tags, move |stored| {
                calls_for_action.fetch_add(1, Ordering::SeqCst);
                if stored
                    .as_live()
                    .expect("test object is live")
                    .tags
                    .is_some()
                {
                    Err("tags already present")
                } else {
                    Ok(stored.version_id())
                }
            })
            .unwrap();
        assert_eq!(result, Err("tags already present"));
        assert!(hook_ran.load(Ordering::SeqCst));
        assert_eq!(
            action_calls.load(Ordering::SeqCst),
            2,
            "request action must be rerun after slot contention changes object state"
        );
        assert!(pending_metadata_command_for_test(&first_map, PgId::new(2), &bucket).is_none());

        for node_id in node_ids {
            let pg = first_map
                .node(node_id)
                .unwrap()
                .storage_node()
                .get_pg(2)
                .unwrap();
            let stored = crate::PgMetadataStore::get_object_meta(&*pg, &bucket, &key).unwrap();
            let live = stored.as_live().expect("test object is live");
            assert_eq!(
                live.tags.as_ref().map(crate::SerializedTagSet::as_str),
                Some(winner_tags.as_str())
            );
        }
        assert_bucket_write_reservations_released(&first_map, &bucket);
    }

    #[test]
    fn direct_put_pending_install_race_reruns_precondition_action() {
        let _guard = lock_metadata_command_apply_hook_test();
        let tmp = test_util::tempdir();
        let node_ids = [NodeId::new(0), NodeId::new(1), NodeId::new(2)];
        let pg_ids = [0, 1, 2, 3];
        let ec_shape = EcShape { k: 2, m: 1 };
        let mut first_map =
            LocalClusterMap::open(tmp.path(), &node_ids, &pg_ids, ec_shape).unwrap();
        let topology = first_map
            .node(NodeId::new(0))
            .unwrap()
            .storage_node()
            .pg_topology();
        let bucket = bucket_for_pg(topology, 1, "direct-put-pending-race-");
        let key = key_for_object_pg(topology, &bucket, 2, "object-");
        set_route_primary(&mut first_map, 1, NodeId::new(1));
        set_route_primary(&mut first_map, 2, NodeId::new(1));

        let mut second_map =
            LocalClusterMap::open(tmp.path(), &node_ids, &pg_ids, ec_shape).unwrap();
        set_route_primary(&mut second_map, 1, NodeId::new(1));
        set_route_primary(&mut second_map, 2, NodeId::new(1));

        let first_map = Arc::new(first_map);
        let second_map = Arc::new(second_map);
        let first_cluster = crate::StorageCluster::from_local_map(Arc::clone(&first_map)).unwrap();
        let second_cluster =
            crate::StorageCluster::from_local_map(Arc::clone(&second_map)).unwrap();
        create_test_bucket(&first_cluster, &bucket);

        let loser_payload = b"loser direct put";
        let loser_reservation_id =
            crate::SessionId::try_from("11111111111111111111111111111111".to_string()).unwrap();
        let loser_generation_id = first_cluster
            .reserve_put_object_generation(&bucket, &key, &loser_reservation_id)
            .unwrap();
        let loser_written = first_cluster
            .write_direct_put_segment_payload_shards(
                &bucket,
                &key,
                loser_generation_id,
                0,
                &[0x91; 16],
                loser_payload,
            )
            .unwrap();
        let loser_req = direct_put_commit_req(
            &first_cluster,
            DirectPutCommitReqFixture {
                bucket: &bucket,
                key: &key,
                reservation_id: loser_reservation_id,
                generation_id: loser_generation_id,
                payload: loser_payload,
                segment_okh: [0x91; 16],
                written: &loser_written,
            },
        );

        let winner_payload = b"winner direct put";
        let winner_reservation_id =
            crate::SessionId::try_from("22222222222222222222222222222222".to_string()).unwrap();
        let winner_generation_id = second_cluster
            .reserve_put_object_generation(&bucket, &key, &winner_reservation_id)
            .unwrap();
        let winner_written = second_cluster
            .write_direct_put_segment_payload_shards(
                &bucket,
                &key,
                winner_generation_id,
                0,
                &[0x92; 16],
                winner_payload,
            )
            .unwrap();
        let winner_req = direct_put_commit_req(
            &first_cluster,
            DirectPutCommitReqFixture {
                bucket: &bucket,
                key: &key,
                reservation_id: winner_reservation_id,
                generation_id: winner_generation_id,
                payload: winner_payload,
                segment_okh: [0x92; 16],
                written: &winner_written,
            },
        );

        let hook_ran = Arc::new(AtomicBool::new(false));
        let action_calls = Arc::new(AtomicUsize::new(0));
        let hook_cluster = Arc::clone(&second_cluster);
        let hook_map = Arc::clone(&second_map);
        let hook_bucket = bucket.clone();
        let hook_req = winner_req.clone();
        let hook_written_shards = winner_written.written_shards.clone();
        let hook_ran_for_closure = Arc::clone(&hook_ran);
        let _hook_guard = first_cluster.test_install_before_metadata_command_pending_install_hook(
            Arc::new(move || {
                if hook_ran_for_closure.swap(true, Ordering::SeqCst) {
                    return;
                }
                let pg_id = PgId::new(2);
                let shard_batch: Vec<(&ShardKey, WriteAck)> = hook_written_shards
                    .iter()
                    .map(|written| (&written.key, written.ack))
                    .collect();
                hook_cluster
                    .register_payload_shard_acks(hook_req.data_pg_id, &shard_batch)
                    .unwrap();
                let primary = hook_map
                    .metadata_pg_primary_node(ClusterEpoch::INITIAL, pg_id)
                    .unwrap();
                let pg = primary.storage_node().get_pg(pg_id.get()).unwrap();
                let command = hook_cluster
                    .prepare_commit_direct_put_object_command(
                        pg_id,
                        &pg,
                        &hook_req,
                        crate::VersionId::Null,
                        hook_req.bucket_write_reservation.clone(),
                    )
                    .unwrap();
                pg.try_insert_pending_metadata_command_slot(
                    primary.node_id().as_u32(),
                    &command,
                    Some(&hook_bucket),
                )
                .unwrap();
            }),
        );

        let calls_for_action = Arc::clone(&action_calls);
        let result = first_cluster
            .commit_direct_put_object_from_payload_shards(
                &loser_req,
                &loser_written.written_shards,
                move |snapshot| {
                    calls_for_action.fetch_add(1, Ordering::SeqCst);
                    if snapshot.existing_etag.is_some() {
                        Err("object already exists")
                    } else {
                        Ok(())
                    }
                },
            )
            .unwrap();
        assert!(matches!(result, Err("object already exists")));
        assert!(hook_ran.load(Ordering::SeqCst));
        assert_eq!(
            action_calls.load(Ordering::SeqCst),
            2,
            "direct PUT precondition must be rerun after slot contention changes object state"
        );
        assert!(pending_metadata_command_for_test(&first_map, PgId::new(2), &bucket).is_none());

        for node_id in node_ids {
            let pg = first_map
                .node(node_id)
                .unwrap()
                .storage_node()
                .get_pg(2)
                .unwrap();
            let stored = crate::PgMetadataStore::get_object_meta(&*pg, &bucket, &key).unwrap();
            let live = stored.as_live().expect("winner object is live");
            assert_eq!(live.generation_id, winner_generation_id);
            assert_eq!(live.size, winner_payload.len() as u64);
        }
    }

    #[test]
    fn direct_put_pending_install_race_keeps_bucket_write_proof_for_retry() {
        let _guard = lock_metadata_command_apply_hook_test();
        let tmp = test_util::tempdir();
        let node_ids = [NodeId::new(0), NodeId::new(1), NodeId::new(2)];
        let pg_ids = [0, 1, 2, 3];
        let ec_shape = EcShape { k: 2, m: 1 };
        let mut first_map =
            LocalClusterMap::open(tmp.path(), &node_ids, &pg_ids, ec_shape).unwrap();
        let topology = first_map
            .node(NodeId::new(0))
            .unwrap()
            .storage_node()
            .pg_topology();
        let bucket = bucket_for_pg(topology, 1, "direct-put-proof-race-");
        let loser_key = key_for_object_pg(topology, &bucket, 2, "loser-");
        let winner_key = key_for_object_pg(topology, &bucket, 2, "winner-");
        set_route_primary(&mut first_map, 1, NodeId::new(1));
        set_route_primary(&mut first_map, 2, NodeId::new(1));

        let mut second_map =
            LocalClusterMap::open(tmp.path(), &node_ids, &pg_ids, ec_shape).unwrap();
        set_route_primary(&mut second_map, 1, NodeId::new(1));
        set_route_primary(&mut second_map, 2, NodeId::new(1));

        let first_map = Arc::new(first_map);
        let second_map = Arc::new(second_map);
        let first_cluster = crate::StorageCluster::from_local_map(Arc::clone(&first_map)).unwrap();
        let second_cluster =
            crate::StorageCluster::from_local_map(Arc::clone(&second_map)).unwrap();
        create_test_bucket(&first_cluster, &bucket);

        let loser_payload = b"loser direct put with command proof";
        let loser_reservation_id =
            crate::SessionId::try_from("51515151515151515151515151515151".to_string()).unwrap();
        let loser_generation_id = first_cluster
            .reserve_put_object_generation(&bucket, &loser_key, &loser_reservation_id)
            .unwrap();
        let loser_written = first_cluster
            .write_direct_put_segment_payload_shards(
                &bucket,
                &loser_key,
                loser_generation_id,
                0,
                &[0xb1; 16],
                loser_payload,
            )
            .unwrap();
        let command_reservation = first_cluster
            .acquire_durable_bucket_write_reservation(
                &bucket,
                "direct-put-proof-race",
                Some(loser_key.as_str()),
            )
            .unwrap();
        let loser_req = direct_put_commit_req_with_bucket_write_proof(
            DirectPutCommitReqFixture {
                bucket: &bucket,
                key: &loser_key,
                reservation_id: loser_reservation_id,
                generation_id: loser_generation_id,
                payload: loser_payload,
                segment_okh: [0xb1; 16],
                written: &loser_written,
            },
            crate::metadata_command::BucketWriteReservationProof::from(&command_reservation.record),
        );

        let winner_payload = b"winner unrelated direct put";
        let winner_reservation_id =
            crate::SessionId::try_from("52525252525252525252525252525252".to_string()).unwrap();
        let winner_generation_id = second_cluster
            .reserve_put_object_generation(&bucket, &winner_key, &winner_reservation_id)
            .unwrap();
        let winner_written = second_cluster
            .write_direct_put_segment_payload_shards(
                &bucket,
                &winner_key,
                winner_generation_id,
                0,
                &[0xb2; 16],
                winner_payload,
            )
            .unwrap();
        let winner_req = direct_put_commit_req(
            &first_cluster,
            DirectPutCommitReqFixture {
                bucket: &bucket,
                key: &winner_key,
                reservation_id: winner_reservation_id,
                generation_id: winner_generation_id,
                payload: winner_payload,
                segment_okh: [0xb2; 16],
                written: &winner_written,
            },
        );

        let hook_ran = Arc::new(AtomicBool::new(false));
        let action_calls = Arc::new(AtomicUsize::new(0));
        let hook_cluster = Arc::clone(&second_cluster);
        let hook_map = Arc::clone(&second_map);
        let hook_bucket = bucket.clone();
        let hook_req = winner_req.clone();
        let hook_written_shards = winner_written.written_shards.clone();
        let hook_ran_for_closure = Arc::clone(&hook_ran);
        let _hook_guard = first_cluster.test_install_before_metadata_command_pending_install_hook(
            Arc::new(move || {
                if hook_ran_for_closure.swap(true, Ordering::SeqCst) {
                    return;
                }
                let pg_id = PgId::new(2);
                let shard_batch: Vec<(&ShardKey, WriteAck)> = hook_written_shards
                    .iter()
                    .map(|written| (&written.key, written.ack))
                    .collect();
                hook_cluster
                    .register_payload_shard_acks(hook_req.data_pg_id, &shard_batch)
                    .unwrap();
                let primary = hook_map
                    .metadata_pg_primary_node(ClusterEpoch::INITIAL, pg_id)
                    .unwrap();
                let pg = primary.storage_node().get_pg(pg_id.get()).unwrap();
                let command = hook_cluster
                    .prepare_commit_direct_put_object_command(
                        pg_id,
                        &pg,
                        &hook_req,
                        crate::VersionId::Null,
                        hook_req.bucket_write_reservation.clone(),
                    )
                    .unwrap();
                pg.try_insert_pending_metadata_command_slot(
                    primary.node_id().as_u32(),
                    &command,
                    Some(&hook_bucket),
                )
                .unwrap();
            }),
        );

        let calls_for_action = Arc::clone(&action_calls);
        first_cluster
            .commit_direct_put_object_from_payload_shards(
                &loser_req,
                &loser_written.written_shards,
                move |snapshot| {
                    calls_for_action.fetch_add(1, Ordering::SeqCst);
                    assert!(snapshot.existing_etag.is_none());
                    Ok::<(), ()>(())
                },
            )
            .unwrap()
            .unwrap();
        assert!(hook_ran.load(Ordering::SeqCst));
        assert_eq!(
            action_calls.load(Ordering::SeqCst),
            2,
            "direct PUT must rerun after install contention while keeping its write proof"
        );
        assert!(pending_metadata_command_for_test(&first_map, PgId::new(2), &bucket).is_none());
        let object_pg = first_map
            .metadata_pg_primary_node(ClusterEpoch::INITIAL, PgId::new(2))
            .unwrap()
            .storage_node()
            .get_pg(2)
            .unwrap();
        let stored =
            crate::PgMetadataStore::get_object_meta(&*object_pg, &bucket, &loser_key).unwrap();
        assert_eq!(stored.as_live().unwrap().generation_id, loser_generation_id);
        drop(object_pg);
        let bucket_pg = first_map
            .metadata_pg_primary_node(ClusterEpoch::INITIAL, PgId::new(1))
            .unwrap()
            .storage_node()
            .get_pg(1)
            .unwrap();
        assert!(
            crate::PgMetadataStore::durable_bucket_write_reservations(&*bucket_pg, &bucket)
                .unwrap()
                .is_empty()
        );
        drop(bucket_pg);
        assert_clean_metadata_command_stream(&first_map, &[2]);
    }

    #[test]
    fn direct_put_pre_command_route_error_releases_bucket_write_proof() {
        let tmp = test_util::tempdir();
        let node_ids = [NodeId::new(0), NodeId::new(1), NodeId::new(2)];
        let pg_ids = [0, 1, 2, 3];
        let ec_shape = EcShape { k: 2, m: 1 };
        let mut local_map =
            LocalClusterMap::open(tmp.path(), &node_ids, &pg_ids, ec_shape).unwrap();
        let (bucket, key, object_pg, data_pg) = {
            let topology = local_map
                .nodes
                .get(&NodeId::new(0))
                .unwrap()
                .storage_node()
                .pg_topology();
            bucket_key_with_distinct_object_and_data_pg(topology)
        };
        set_route_primary(&mut local_map, object_pg, NodeId::new(1));
        set_route_primary(&mut local_map, data_pg, NodeId::new(2));

        let mut map = Arc::new(local_map);
        let cluster = crate::StorageCluster::from_local_map(Arc::clone(&map)).unwrap();
        create_test_bucket(&cluster, &bucket);
        let bucket_pg_id = cluster.bucket_metadata_pg_id(&bucket);
        let reservation_id =
            crate::SessionId::try_from("53535353535353535353535353535353".to_string()).unwrap();
        let generation_id = cluster
            .reserve_put_object_generation(&bucket, &key, &reservation_id)
            .unwrap();
        let payload = b"direct put route failure";
        let segment_okh = [0xb3; 16];
        let written = cluster
            .write_direct_put_segment_payload_shards(
                &bucket,
                &key,
                generation_id,
                0,
                &segment_okh,
                payload,
            )
            .unwrap();
        let command_reservation = cluster
            .acquire_durable_bucket_write_reservation(
                &bucket,
                "direct-put-route-failure",
                Some(key.as_str()),
            )
            .unwrap();
        let commit_req = direct_put_commit_req_with_bucket_write_proof(
            DirectPutCommitReqFixture {
                bucket: &bucket,
                key: &key,
                reservation_id,
                generation_id,
                payload,
                segment_okh,
                written: &written,
            },
            crate::metadata_command::BucketWriteReservationProof::from(&command_reservation.record),
        );
        drop(cluster);

        Arc::get_mut(&mut map)
            .unwrap()
            .pg_routes
            .get_mut(&PgId::new(object_pg))
            .unwrap()
            .state = PgState::Peering;
        let cluster = crate::StorageCluster::from_local_map(Arc::clone(&map)).unwrap();
        let err = cluster
            .commit_direct_put_object_from_payload_shards(
                &commit_req,
                &written.written_shards,
                |_| Ok::<(), ()>(()),
            )
            .unwrap_err();
        assert!(matches!(
            err,
            crate::ObjectPgActionError::Store(StoreError::PgNotActive {
                pg_id,
                state: PgState::Peering,
                ..
            }) if pg_id == object_pg
        ));

        let bucket_pg = map
            .metadata_pg_primary_node(ClusterEpoch::INITIAL, PgId::new(bucket_pg_id))
            .unwrap()
            .storage_node()
            .get_pg(bucket_pg_id)
            .unwrap();
        assert!(
            crate::PgMetadataStore::durable_bucket_write_reservations(&*bucket_pg, &bucket)
                .unwrap()
                .is_empty(),
            "pre-command storage errors must release caller-owned bucket write proof"
        );
    }

